// commands.t27 -- CLI Command Specifications
// Individual command specifications for tri CLI
// phi^2 + 1/phi^2 = 3 | TRINITY

module commands {
    // =====================================================================
    // Command Enum
    // =====================================================================

    pub const Command = enum(u8) {
        SpecCommand,          // spec create, validate, list
        GenCommand,           // gen <spec>, gen --all
        CompileProjectCommand, // compile-project: multi-file with resolved imports
        GitCommand,           // git commit, push, status
        LintCommand,          // lint [file], lint --all
        SkillCommand,         // skill begin, seal, status
        HelpCommand,          // help
    };

    // =====================================================================
    // Command: tri spec
    // =====================================================================

    // tri spec create <name> [--kind feature|bugfix|hotfix|recovery]
    pub fn spec_create(name: []const u8, kind: []const u8) i32 {
        // Validate name
        if (name.len == 0) {
            error_print("ERROR: spec name cannot be empty");
            return 1;
        }

        // Validate kind
        const valid_kinds = [_][]const u8{ "feature", "bugfix", "hotfix", "recovery" };
        var valid = false;
        for (valid_kinds) |k| {
            if (std.mem.eql(u8, kind, k)) {
                valid = true;
                break;
            }
        }

        if (!valid) {
            error_print("ERROR: invalid kind: ");
            error_print(kind);
            error_print("\nValid kinds: feature, bugfix, hotfix, recovery");
            return 1;
        }

        // Create spec file
        const spec_path = "specs/" ++ name ++ ".t27";

        if (file_exists(spec_path)) {
            error_print("ERROR: spec already exists: ");
            error_print(spec_path);
            return 1;
        }

        const spec_content = generate_spec_template(name, kind);
        write_file(spec_path, spec_content);

        print("Created spec: ");
        print(spec_path);
        print("\nKind: ");
        print(kind);
        print("\n");
        print("NOTE: Spec must contain at least one 'test' or 'invariant' block");
        print("Run 'tri gen ");
        print(spec_path);
        print("' to generate code");

        return 0;
    }

    // tri spec validate <spec_path>
    pub fn spec_validate(spec_path: []const u8) i32 {
        // Check if spec exists
        if (!file_exists(spec_path)) {
            error_print("ERROR: spec not found: ");
            error_print(spec_path);
            return 1;
        }

        // Parse spec
        const spec = parse_spec(spec_path);
        if (spec == null) {
            error_print("ERROR: failed to parse spec: ");
            error_print(spec_path);
            return 1;
        }

        // Check TDD contract
        if (spec.?.test_blocks.len == 0 and spec.?.invariant_blocks.len == 0) {
            error_print("ERROR: TDD contract violated");
            error_print("Spec must contain at least one 'test' or 'invariant' block");
            error_print("See: docs/TDD-CONTRACT.md");
            return 1;
        }

        // Check language policy
        if (contains_cyrillic(spec.?.content) and !is_docs_path(spec_path)) {
            error_print("ERROR: Language policy violated");
            error_print("Source files must not contain Cyrillic characters");
            error_print("See: ADR-004-language-policy.md");
            return 1;
        }

        // Validate structure
        const validation_result = validate_spec_structure(spec.?);
        if (validation_result != 0) {
            return validation_result;
        }

        print("Valid: ");
        print(spec_path);
        print("\n  Tests: ");
        print_int(spec.?.test_blocks.len);
        print("\n  Invariants: ");
        print_int(spec.?.invariant_blocks.len);

        return 0;
    }

    // tri spec list
    pub fn spec_list() i32 {
        const spec_files = list_files("specs/**/*.t27");

        if (spec_files.len == 0) {
            print("No spec files found in specs/");
            return 0;
        }

        print("Spec files (");
        print_int(spec_files.len);
        print("):\n");

        for (spec_files) |spec_path| {
            const spec = parse_spec(spec_path);
            const status = if (spec != null) blk: {
                var buf: [64]u8 = undefined;
                const t_count = std.fmt.bufPrintInt(&buf, spec.?.test_blocks.len, 10, .lower, .{}) catch "";
                const i_count = std.fmt.bufPrintInt(&buf, spec.?.invariant_blocks.len, 10, .lower, .{}) catch "";
                break :blk "T:" ++ t_count ++ " I:" ++ i_count;
            } else {
                "ERROR"
            };
            print("  ");
            print(spec_path);
            print(" [");
            print(status);
            print("]\n");
        }

        return 0;
    }

    // =====================================================================
    // Command: tri gen
    // =====================================================================

    // tri gen <spec_path> [--backend zig|c|verilog] [--emit-conformance]
    pub fn gen_spec(spec_path: []const u8, backend: []const u8, emit_conformance: bool) i32 {
        // Validate spec first
        const validation = spec_validate(spec_path);
        if (validation != 0) {
            error_print("ERROR: spec validation failed, cannot generate code");
            return validation;
        }

        // Parse spec
        const spec = parse_spec(spec_path);
        if (spec == null) {
            error_print("ERROR: failed to parse spec");
            return 1;
        }

        // Generate backend code
        var result: i32 = 0;
        if (std.mem.eql(u8, backend, "zig")) {
            result = generate_zig(spec.?);
        } else if (std.mem.eql(u8, backend, "c")) {
            result = generate_c(spec.?);
        } else if (std.mem.eql(u8, backend, "verilog")) {
            result = generate_verilog(spec.?);
        } else {
            error_print("ERROR: unknown backend: ");
            error_print(backend);
            return 1;
        }

        if (result != 0) {
            error_print("ERROR: code generation failed");
            return result;
        }

        // Generate conformance if requested
        if (emit_conformance) {
            const conformance_result = generate_conformance(spec.?);
            if (conformance_result != 0) {
                error_print("WARNING: conformance generation failed");
            }
        }

        print("Generated code from: ");
        print(spec_path);
        print("\n  Backend: ");
        print(backend);

        return 0;
    }

    // tri gen --all
    pub fn gen_all(backend: []const u8) i32 {
        const spec_files = list_files("specs/**/*.t27");
        var failed: i32 = 0;

        for (spec_files) |spec_path| {
            const result = gen_spec(spec_path, backend, false);
            if (result != 0) {
                failed += 1;
                error_print("Failed to generate: ");
                error_print(spec_path);
            }
        }

        const total = spec_files.len;
        const success = @as(i32, @intCast(total)) - failed;

        print("\nGeneration complete:\n");
        print("  Total: ");
        print_int(total);
        print("\n  Success: ");
        print_int(success);
        print("\n  Failed: ");
        print_int(failed);

        return if (failed > 0) 1 else 0;
    }

    // =====================================================================
    // Command: tri compile-project
    // =====================================================================

    // tri compile-project --output <dir> [--backend zig|c|verilog]
    // Generates ALL specs into a coherent project with working inter-file imports.
    //
    // Pass 1: Scan all .t27 files, build module -> file path map
    // Pass 2: For each file, resolve `use X::Y` to correct relative path
    // Pass 3: Write all files + build.zig to output directory
    pub fn compile_project(output_dir: []const u8, backend: []const u8) i32 {
        // Validate backend
        if (!std.mem.eql(u8, backend, "zig") and
            !std.mem.eql(u8, backend, "c") and
            !std.mem.eql(u8, backend, "verilog"))
        {
            error_print("ERROR: unknown backend: ");
            error_print(backend);
            error_print("\nValid backends: zig, c, verilog");
            return 1;
        }

        // Pass 1: Scan all .t27 files and build module map
        const spec_files = list_files("specs/**/*.t27");
        const compiler_files = list_files("compiler/**/*.t27");
        const all_files = concat(spec_files, compiler_files);

        var module_map: ModuleMap = undefined;
        module_map.init();

        for (all_files) |file_path| {
            const source = read_file(file_path);
            if (source == null) continue;

            const rel_path = strip_prefix(file_path);
            const module_key = path_to_module_key(rel_path);
            module_map.put(module_key, rel_path);
        }

        print("Module map: ");
        print_int(module_map.count());
        print(" entries\n");

        // Pass 2: Compile each file with resolved imports
        var success: i32 = 0;
        var failed: i32 = 0;

        for (all_files) |file_path| {
            const source = read_file(file_path);
            if (source == null) {
                failed += 1;
                continue;
            }

            const rel_path = strip_prefix(file_path);
            const code = compile_with_resolved_imports(source.?, rel_path, backend, module_map);

            if (code == null) {
                failed += 1;
                error_print("Failed: ");
                error_print(file_path);
                error_print("\n");
                continue;
            }

            const ext = backend_extension(backend);
            const dest = output_dir ++ "/" ++ replace(rel_path, ".t27", ext);
            const dir = dir_path(dest);
            create_dir_if_not_exists(dir);
            write_file(dest, code.?);
            success += 1;
        }

        // Pass 3: Generate build.zig (Zig backend only)
        if (std.mem.eql(u8, backend, "zig")) {
            const build_zig = generate_build_zig(all_files, output_dir);
            write_file(output_dir ++ "/build.zig", build_zig);
            print("Generated build.zig\n");
        }

        print("\ncompile-project complete:\n");
        print("  Output: ");
        print(output_dir);
        print("\n  Success: ");
        print_int(success);
        print("\n  Failed: ");
        print_int(failed);

        return if (failed > 0) 1 else 0;
    }

    // =====================================================================
    // Command: tri lint
    // =====================================================================

    // tri lint [file] [--strict]
    pub fn lint_file(file_path: []const u8, strict: bool) i32 {
        // Check file extension
        if (!std.mem.endsWith(u8, file_path, ".t27")) {
            error_print("ERROR: .t27 file required");
            return 1;
        }

        // Validate spec
        const result = spec_validate(file_path);
        if (result != 0) {
            return result;
        }

        // Strict mode checks
        if (strict) {
            const spec = parse_spec(file_path);
            if (spec.?.test_blocks.len == 0 and spec.?.invariant_blocks.len == 0) {
                error_print("ERROR: strict mode requires tests");
                return 1;
            }
        }

        print("Lint passed: ");
        print(file_path);
        return 0;
    }

    // tri lint --all
    pub fn lint_all(strict: bool) i32 {
        const spec_files = list_files("specs/**/*.t27");
        var failed: i32 = 0;

        for (spec_files) |spec_path| {
            const result = lint_file(spec_path, strict);
            if (result != 0) {
                failed += 1;
            }
        }

        if (failed > 0) {
            error_print("Lint failed: ");
            print_int(failed);
            error_print(" files");
            return 1;
        }

        print("All specs passed lint");
        return 0;
    }

    // =====================================================================
    // Command: tri skill
    // =====================================================================

    // tri skill begin --issue <N> [--kind feature|bugfix|hotfix|recovery]
    pub fn skill_begin(issue_id: []const u8, kind: []const u8) i32 {
        const registry_path = ".trinity/skills/registry.json";

        // Validate issue ID
        if (issue_id.len == 0) {
            error_print("ERROR: issue ID required");
            error_print("Usage: tri skill begin --issue <N>");
            return 1;
        }

        // Load or create registry
        const registry = load_or_create_registry(registry_path);

        // Create new skill
        var skill_id_buf: [32]u8 = undefined;
        const skill_id = std.fmt.bufPrint(&skill_id_buf, "skill-{d}", .{registry.skills.len + 1}) catch "";
        const timestamp = get_current_timestamp();
        const branch = git_get_current_branch();

        const new_skill = Skill{
            .id = skill_id,
            .status = "active",
            .kind = kind,
            .issue = issue_id,
            .branch = branch,
            .created_at = timestamp,
            .updated_at = timestamp,
            .sealed_at = null,
            .commit = null,
            .commit_at = null,
            .pushed = false,
            .pushed_at = null,
            .verdict = null,
            .verdict_at = null,
            .seal_hash = null,
            .artifacts = "",
            .metadata = SkillMetadata{
                .title = "",
                .author = "cli",
                .priority = "P1",
                .tags = &[_][]const u8{},
            },
        };

        registry.skills.append(new_skill);
        write_registry(registry_path, registry);

        print("Skill started:\n");
        print("  ID: ");
        print(skill_id);
        print("\n  Issue: ");
        print(issue_id);
        print("\n  Kind: ");
        print(kind);
        print("\n  Branch: ");
        print(branch);

        return 0;
    }

    // tri skill seal
    pub fn skill_seal() i32 {
        const registry_path = ".trinity/skills/registry.json";

        if (!file_exists(registry_path)) {
            error_print("ERROR: no active skill found");
            error_print("Run 'tri skill begin --issue N' first");
            return 1;
        }

        const registry = load_registry(registry_path);
        const skill = find_active_skill(registry);

        if (skill == null) {
            error_print("ERROR: no active skill found");
            return 1;
        }

        // Seal the skill
        const timestamp = get_current_timestamp();
        skill.?.status = "sealed";
        skill.?.sealed_at = timestamp;
        skill.?.seal_hash = compute_seal_hash(skill.?);
        skill.?.updated_at = timestamp;

        write_registry(registry_path, registry);

        print("Skill sealed:\n");
        print("  ID: ");
        print(skill.?.id);
        print("\n  Seal hash: ");
        print(skill.?.seal_hash orelse "");
        print("\n");
        print("Run 'tri git commit' and 'tri git push' to complete");

        return 0;
    }

    // tri skill status
    pub fn skill_status() i32 {
        const registry_path = ".trinity/skills/registry.json";

        if (!file_exists(registry_path)) {
            print("No skill registry found");
            print("Run 'tri skill begin --issue N' to start a skill");
            return 0;
        }

        const registry = load_registry(registry_path);
        const skill = find_active_or_sealed_skill(registry);

        if (skill == null) {
            print("No active or sealed skill found");
            return 0;
        }

        print("Current skill:\n");
        print("  ID: ");
        print(skill.?.id);
        print("\n  Status: ");
        print(skill.?.status);
        print("\n  Kind: ");
        print(skill.?.kind);
        print("\n  Issue: ");
        print(skill.?.issue);
        print("\n  Branch: ");
        print(skill.?.branch);

        if (skill.?.verdict) |verdict| {
            print("\n  Verdict: ");
            print(verdict);
        }

        if (skill.?.artifacts.len > 0) {
            print("\n  Artifacts: ");
            print(skill.?.artifacts);
        }

        return 0;
    }

