    // =====================================================================
    // Helper functions
    // =====================================================================

    fn generate_spec_template(name: []const u8, kind: []const u8) []const u8 {
        return "// " ++ name ++ ".t27 -- " ++ kind ++ " specification\n" ++
               "// Generated by: tri spec create\n" ++
               "// phi^2 + 1/phi^2 = 3 | TRINITY\n" ++
               "\n" ++
               "// =====================================================================\n" ++
               "// TDD-Inside-Spec: This spec MUST contain at least one test or invariant\n" ++
               "// =====================================================================\n" ++
               "\n" ++
               "test my_test\n" ++
               "    // Verify: functionality works correctly\n" ++
               "    try std.testing.expect(true);\n" ++
               "\n" ++
               "invariant my_invariant\n" ++
               "    // For all valid inputs: output is in valid range\n" ++
               "    assert true;\n";
    }

    fn generate_zig(spec: Spec) i32 {
        // Generate Zig code with proper header
        const header = "// This file is generated from " ++ spec.path ++ "\n" ++
                      "// DO NOT EDIT - Changes will be overwritten on next tri gen\n" ++
                      "// Generated at: " ++ get_current_timestamp() ++ "\n" ++
                      "// Source spec: " ++ spec.path ++ "\n\n";

        const code = generate_zig_impl(spec);
        var output_path = spec.path;
        output_path = replace(output_path, ".t27", ".zig");
        output_path = replace(output_path, "specs/", "src/");

        // Ensure output directory exists
        const dir = dir_path(output_path);
        create_dir_if_not_exists(dir);

        write_file(output_path, header ++ code);
        return 0;
    }

    fn generate_c(spec: Spec) i32 {
        // Similar to generate_zig but for C
        _ = spec;
        return 0;
    }

    fn generate_verilog(spec: Spec) i32 {
        // Similar to generate_zig but for Verilog
        _ = spec;
        return 0;
    }

    fn generate_conformance(spec: Spec) i32 {
        // Generate conformance JSON from test blocks
        const conformance = Conformance{
            .version = "1.0",
            .spec = spec.path,
            .tests = extract_tests(spec),
        };

        const output_path = "conformance/" ++ replace(replace(spec.path, ".t27", ""), "specs/", "") ++ ".json";
        write_file(output_path, serialize_json(conformance));
        return 0;
    }

    fn load_or_create_registry(path: []const u8) SkillRegistry {
        if (file_exists(path)) {
            return load_registry(path);
        } else {
            return SkillRegistry{
                .version = "1.0",
                .skills = &[_]Skill{},
            };
        }
    }

    fn compute_seal_hash(skill: Skill) []const u8 {
        // Compute hash of skill state for seal verification
        const data = skill.id ++ skill.status ++ skill.issue ++ skill.updated_at;
        return sha256(data);
    }

    // =====================================================================
    // Type definitions
    // =====================================================================

    pub const Spec = struct {
        path: []const u8,
        content: []const u8,
        test_blocks: []TestBlock,
        invariant_blocks: []InvariantBlock,
    };

    pub const TestBlock = struct {
        statements: []const u8,
    };

    pub const InvariantBlock = struct {
        statements: []const u8,
    };

    pub const Skill = struct {
        id: []const u8,
        status: []const u8,
        kind: []const u8,
        issue: []const u8,
        branch: []const u8,
        created_at: []const u8,
        updated_at: []const u8,
        sealed_at: ?[]const u8,
        commit: ?[]const u8,
        commit_at: ?[]const u8,
        pushed: bool,
        pushed_at: ?[]const u8,
        verdict: ?[]const u8,
        verdict_at: ?[]const u8,
        seal_hash: ?[]const u8,
        artifacts: []const u8,
        metadata: SkillMetadata,
    };

    pub const SkillMetadata = struct {
        title: []const u8,
        author: []const u8,
        priority: []const u8,
        tags: [][]const u8,
    };

    pub const SkillRegistry = struct {
        version: []const u8,
        skills: []Skill,
    };

    pub const Conformance = struct {
        version: []const u8,
        spec: []const u8,
        tests: []TestBlock,
    };

    // =====================================================================
    // Module Map for compile-project
    // =====================================================================

    pub const ModuleMapEntry = struct {
        key: []const u8,    // e.g. "base::types"
        path: []const u8,   // e.g. "base/types"
    };

    pub const ModuleMap = struct {
        entries: [256]ModuleMapEntry,
        count_val: usize,

        pub fn init(self: *ModuleMap) void {
            self.count_val = 0;
        }

        pub fn put(self: *ModuleMap, key: []const u8, path: []const u8) void {
            if (self.count_val < 256) {
                self.entries[self.count_val] = ModuleMapEntry{ .key = key, .path = path };
                self.count_val += 1;
            }
        }

        pub fn get(self: ModuleMap, key: []const u8) ?[]const u8 {
            for (self.entries[0..self.count_val]) |entry| {
                if (std.mem.eql(u8, entry.key, key)) {
                    return entry.path;
                }
            }
            return null;
        }

        pub fn count(self: ModuleMap) usize {
            return self.count_val;
        }
    };

    fn path_to_module_key(rel_path: []const u8) []const u8 {
        // Convert "base/types.t27" -> "base::types"
        var result = replace(rel_path, ".t27", "");
        result = replace(result, "/", "::");
        return result;
    }

    fn backend_extension(backend: []const u8) []const u8 {
        if (std.mem.eql(u8, backend, "verilog")) return ".v";
        if (std.mem.eql(u8, backend, "c")) return ".c";
        return ".zig";
    }

    fn strip_prefix(file_path: []const u8) []const u8 {
        // Strip "specs/" or "compiler/" prefix
        if (std.mem.startsWith(u8, file_path, "specs/")) {
            return file_path[6..];
        }
        if (std.mem.startsWith(u8, file_path, "compiler/")) {
            return file_path[9..];
        }
        return file_path;
    }
}

