// SPDX-License-Identifier: Apache-2.0
// provider/transform.t27 — Cross-Provider Message Transformations
// Message format transformations between different AI providers
// φ² + 1/φ² = 3 | TRINITY

module provider-transform;

// ============================================================================
// Imports
// ============================================================================

use tritype-base::usize;
use provider-schema::Message;
use provider-schema::MessageRole;
use provider-schema::MessageContent;
use provider-schema::ContentType;
use provider-schema::Tool;
use provider-schema::ProviderType;

// ============================================================================
// Constants
// ============================================================================

/// Maximum message history length
pub const MAX_HISTORY_LENGTH : usize = 100;

/// Maximum content length per message
pub const MAX_CONTENT_LENGTH : usize = 100000;

/// Default system prompt for transformations
pub const DEFAULT_SYSTEM_PROMPT : [17]u8 = "You are a helpful assistant.";

// ============================================================================
// Types
// ============================================================================

/// Transform direction
pub const TransformDirection = enum(u8) {
    anthropic_to_openai = 0,
    openai_to_anthropic = 1,
    anthropic_to_anthropic = 2,
    openai_to_openai = 3,
};

/// Transform result
pub const TransformResult = struct {
    success : bool,
    messages : []Message,
    tools : []Tool,
    error : []u8,
};

/// Message mapping
pub const MessageMapping = struct {
    source_role : MessageRole,
    target_role : MessageRole,
    content_transform : ContentTransform,
};

/// Content transform
pub const ContentTransform = enum(u8) {
    identity = 0,
    escape_tool_calls = 1,
    unescape_tool_calls = 2,
    normalize_images = 3,
};

/// Tool mapping
pub const ToolMapping = struct {
    source_name : []u8,
    target_name : []u8,
    parameter_transform : ParameterTransform,
};

/// Parameter transform
pub const ParameterTransform = enum(u8) {
    identity = 0,
    rename_field = 1,
    convert_type = 2,
};

/// Transform options
pub const TransformOptions = struct {
    preserve_system : bool,
    preserve_tools : bool,
    normalize_content : bool,
};

/// Batch transform result
pub const BatchTransformResult = struct {
    results : []TransformResult,
    total_success : usize,
    total_failed : usize,
};

/// Transform error
pub const TransformError = struct {
    code : i32,
    message : []u8,
    source_provider : ProviderType,
    target_provider : ProviderType,
};

/// Transformed message
pub const TransformedMessage = struct {
    original : Message,
    transformed : Message,
    applied_transforms : []ContentTransform,
};

// ============================================================================
// Functions
// ============================================================================

/// Create transform options
pub fn transform_options_default() TransformOptions {
    return TransformOptions{
        .preserve_system = true,
        .preserve_tools = true,
        .normalize_content = true,
    };
}

/// Create transform direction
pub fn transform_direction_create(source: ProviderType, target: ProviderType) TransformDirection {
    if (source == .anthropic and target == .openai) {
        return .anthropic_to_openai;
    } else if (source == .openai and target == .anthropic) {
        return .openai_to_anthropic;
    } else {
        return .anthropic_to_anthropic;
    }
}

/// Create transform result
pub fn transform_result_create(success: bool, messages: []Message) TransformResult {
    return TransformResult{
        .success = success,
        .messages = messages,
        .tools = &[_]Tool{},
        .error = "",
    };
}

/// Create transform result with error
pub fn transform_result_error(code: i32, message: []u8) TransformResult {
    return TransformResult{
        .success = false,
        .messages = &[_]Message{},
        .tools = &[_]Tool{},
        .error = message,
    };
}

/// Create message mapping
pub fn message_mapping_create(source: MessageRole, target: MessageRole) MessageMapping {
    return MessageMapping{
        .source_role = source,
        .target_role = target,
        .content_transform = .identity,
    };
}

/// Create tool mapping
pub fn tool_mapping_create(source: []u8, target: []u8) ToolMapping {
    return ToolMapping{
        .source_name = source,
        .target_name = target,
        .parameter_transform = .identity,
    };
}

/// Create transform error
pub fn transform_error_create(code: i32, message: []u8, source: ProviderType, target: ProviderType) TransformError {
    return TransformError{
        .code = code,
        .message = message,
        .source_provider = source,
        .target_provider = target,
    };
}

/// Create transformed message
pub fn transformed_message_create(original: Message, transformed: Message) TransformedMessage {
    return TransformedMessage{
        .original = original,
        .transformed = transformed,
        .applied_transforms = &[_]ContentTransform{ .identity },
    };
}

/// Transform messages between providers
pub fn transform_messages(source: ProviderType, target: ProviderType, messages: []Message, options: TransformOptions) TransformResult {
    const direction = transform_direction_create(source, target);
    var result_messages : []Message = undefined;
    var result_tools : []Tool = undefined;

    for (messages) |msg| {
        const transformed = transform_single_message(direction, msg, options);
        if (transformed.content.len > 0) {
            result_messages = result_messages ++ &[_]Message{ transformed };
        }
    }

    return TransformResult{
        .success = true,
        .messages = result_messages,
        .tools = result_tools,
        .error = "",
    };
}

/// Transform single message
pub fn transform_single_message(direction: TransformDirection, msg: Message, options: TransformOptions) Message {
    const target_role = map_role(direction, msg.role);
    var transformed_content : []MessageContent = undefined;

    for (msg.content) |content| {
        const new_content = transform_content(direction, content, options);
        transformed_content = transformed_content ++ &[_]MessageContent{ new_content };
    }

    return Message{
        .role = target_role,
        .content = transformed_content,
    };
}

/// Map role between providers
pub fn map_role(direction: TransformDirection, role: MessageRole) MessageRole {
    return switch (direction) {
        .anthropic_to_openai => map_role_anthropic_to_openai(role),
        .openai_to_anthropic => map_role_openai_to_anthropic(role),
        .anthropic_to_anthropic => role,
        .openai_to_openai => role,
    };
}

/// Map role from Anthropic to OpenAI
pub fn map_role_anthropic_to_openai(role: MessageRole) MessageRole {
    return switch (role) {
        .system => .system,
        .user => .user,
        .assistant => .assistant,
        .tool => .assistant,
    };
}

/// Map role from OpenAI to Anthropic
pub fn map_role_openai_to_anthropic(role: MessageRole) MessageRole {
    return switch (role) {
        .system => .system,
        .user => .user,
        .assistant => .assistant,
        .tool => .tool,
    };
}

/// Transform content based on direction
pub fn transform_content(direction: TransformDirection, content: MessageContent, options: TransformOptions) MessageContent {
    if (!options.normalize_content) {
        return content;
    }

    return switch (direction) {
        .anthropic_to_openai => normalize_for_openai(content),
        .openai_to_anthropic => normalize_for_anthropic(content),
        .anthropic_to_anthropic => content,
        .openai_to_openai => content,
    };
}

/// Normalize content for OpenAI
pub fn normalize_for_openai(content: MessageContent) MessageContent {
    return switch (content.type) {
        .text => content,
        .image => normalize_image_for_openai(content),
        .tool_use => convert_tool_to_openai(content),
        .tool_result => content,
    };
}

/// Normalize content for Anthropic
pub fn normalize_for_anthropic(content: MessageContent) MessageContent {
    return switch (content.type) {
        .text => content,
        .image => normalize_image_for_anthropic(content),
        .tool_use => content,
        .tool_result => convert_tool_to_anthropic(content),
    };
}

/// Normalize image for OpenAI
pub fn normalize_image_for_openai(content: MessageContent) MessageContent {
    return content;
}

/// Normalize image for Anthropic
pub fn normalize_image_for_anthropic(content: MessageContent) MessageContent {
    return content;
}

/// Convert tool call to OpenAI format
pub fn convert_tool_to_openai(content: MessageContent) MessageContent {
    return content;
}

/// Convert tool result to Anthropic format
pub fn convert_tool_to_anthropic(content: MessageContent) MessageContent {
    return content;
}

/// Transform tools between providers
pub fn transform_tools(source: ProviderType, target: ProviderType, tools: []Tool) []Tool {
    if (source == target) {
        return tools;
    }

    var result : []Tool = undefined;
    for (tools) |tool| {
        const transformed = transform_single_tool(source, target, tool);
        result = result ++ &[_]Tool{ transformed };
    }
    return result;
}

/// Transform single tool
pub fn transform_single_tool(source: ProviderType, target: ProviderType, tool: Tool) Tool {
    return Tool{
        .name = tool.name,
        .description = tool.description,
        .input_schema = tool.input_schema,
    };
}

/// Check if transformation is needed
pub fn needs_transformation(source: ProviderType, target: ProviderType) bool {
    return source != target;
}

/// Get transform direction string
pub fn transform_direction_to_string(dir: TransformDirection) []u8 {
    return switch (dir) {
        .anthropic_to_openai => "anthropic_to_openai",
        .openai_to_anthropic => "openai_to_anthropic",
        .anthropic_to_anthropic => "anthropic_to_anthropic",
        .openai_to_openai => "openai_to_openai",
    };
}

/// Check if transform result is successful
pub fn is_transform_success(result: TransformResult) bool {
    return result.success;
}

