// t27/specs/physics/gamma_conjecture.t27
// Strand I -- Loop Quantum Gravity
// Conjecture GI1: Barbero-Immirzi Parameter from Golden Section
module GammaConjecture {
    // Import base constants: PHI, PI
    use math::constants;

// -----------------------------------------------------
// 1. Conjecture GI1 Definition
// -----------------------------------------------------
// Claim ID: C-gamma-001 (CONJECTURAL)

    // Trinity gamma conjecture: gamma_phi = phi^{-3}
    // Algebraic forms: sqrt(5) - 2, 1/(2*phi + 1)
    // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
    const GAMMA_PHI : f64 = pow(PHI, -3.0);

    // LQG standard (Meissner 2004): gamma_1 = ln(2)/(pi*sqrt(3))
    // Reference: Loop Quantum Gravity literature
    // Claim: REFERENCE (external LQG), tolerance: N/A
    const GAMMA_LQG_STANDARD : f64 = (2.0_f64.ln()) / (PI * 3.0_f64.sqrt());

    // LQG alternative (Ghosh-Mitra): gamma_2 from black hole entropy fit
    // Reference: Ghosh, Mitra (2010s)
    // Claim: REFERENCE (external LQG), tolerance: N/A
    const GAMMA_LQG_ALT : f64 = 0.27398563520394157868_f64;

    // Delta between gamma_1 and gamma_phi (relative percentage)
    const DELTA_GAMMA_1_PHI_PERCENT : f64 =
        ((GAMMA_LQG_STANDARD - GAMMA_PHI).abs() / GAMMA_LQG_STANDARD) * 100.0;

    // Delta between gamma_2 and gamma_1 (relative percentage)
    const DELTA_GAMMA_2_1_PERCENT : f64 =
        ((GAMMA_LQG_ALT - GAMMA_LQG_STANDARD).abs() / GAMMA_LQG_STANDARD) * 100.0;

// -----------------------------------------------------
// 2. Formula Definitions (affected by gamma)
// -----------------------------------------------------
// Claim IDs: C-gamma-002 to C-gamma-006

    // G1: Newton's constant G = pi^3 * gamma^2 / phi
    // Claim: C-gamma-002 (EMPIRICAL_FIT), tolerance: WITHIN_UNCERTAINTY
    fn newtons_constant_from_gamma(gamma: f64, pi: f64) -> f64 {
        const pi_sq = pi * pi;
        const pi_cub = pi_sq * pi;
        const gamma_sq = gamma * gamma;
        return (pi_cub * gamma_sq) / PHI;
    }

    // BH1: Black hole entropy S = gamma * A / pi
    // Claim: C-gamma-003 (CONJECTURAL), tolerance: CONJECTURAL
    fn black_hole_entropy_from_gamma(gamma: f64, area: f64) -> f64 {
        return gamma * area / PI;
    }

    // SH1: Black hole shadow angular radius theta = 3*sqrt(3)*gamma*M/r
    // Claim: C-gamma-004 (CONJECTURAL), tolerance: CONJECTURAL
    fn black_hole_shadow_from_gamma(gamma: f64, mass: f64, radius: f64) -> f64 {
        return 3.0 * 3.0_f64.sqrt() * gamma * mass / radius;
    }

    // SC3: Superconductivity critical temperature Tc = gamma^2 / pi * scale
    // Claim: C-gamma-005 (CONJECTURAL), tolerance: CONJECTURAL
    fn superconductor_tc_sc3(gamma: f64, scale: f64) -> f64 {
        const gamma_sq = gamma * gamma;
        return (gamma_sq / PI) * scale;
    }

    // SC4: Superconductivity critical temperature Tc = gamma * pi / phi * scale
    // Claim: C-gamma-006 (CONJECTURAL), tolerance: CONJECTURAL
    fn superconductor_tc_sc4(gamma: f64, scale: f64) -> f64 {
        return (gamma * PI / PHI) * scale;
    }

// -----------------------------------------------------
// 3. Verification API
// -----------------------------------------------------

    struct GammaConjectureReport {
        gamma_phi_value    : f64;
        gamma_1_value      : f64;
        gamma_2_value      : f64;
        delta_1_phi        : f64;    // % difference
        delta_2_1         : f64;    // % difference

        g_pred_gamma_phi    : f64;
        g_pred_gamma_1      : f64;

        bh_entropy_phi      : f64;
        bh_entropy_1        : f64;
    }

    fn verify_gamma_conjecture(area: f64, mass: f64, radius: f64, scale: f64) -> GammaConjectureReport {
        const PI = PI;
        const g_phi = newtons_constant_from_gamma(GAMMA_PHI, PI);
        const g_1 = newtons_constant_from_gamma(GAMMA_LQG_STANDARD, PI);
        const bh_s_phi = black_hole_entropy_from_gamma(GAMMA_PHI, area);
        const bh_s_1 = black_hole_entropy_from_gamma(GAMMA_LQG_STANDARD, area);

        return GammaConjectureReport{
            gamma_phi_value   = GAMMA_PHI,
            gamma_1_value     = GAMMA_LQG_STANDARD,
            gamma_2_value     = GAMMA_LQG_ALT,
            delta_1_phi       = DELTA_GAMMA_1_PHI_PERCENT,
            delta_2_1        = DELTA_GAMMA_2_1_PERCENT,

            g_pred_gamma_phi   = g_phi,
            g_pred_gamma_1     = g_1,

            bh_entropy_phi     = bh_s_phi,
            bh_entropy_1       = bh_s_1,
        };
    }

    // =======================================================================================================
    // TDD-Inside-Spec: Tests and Invariants for Gamma Conjecture GI1
    // =======================================================================================================

    test gamma_phi_from_phi_inverse_cubed
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        given gamma_expected = pow(PHI, -3.0)
        and   gamma_actual = GAMMA_PHI
        then abs(gamma_expected - gamma_actual) < 1e-15

    test gamma_phi_equals_sqrt_five_minus_two
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        given gamma_phi = GAMMA_PHI
        and   sqrt_form = 5.0_f64.sqrt() - 2.0
        then abs(gamma_phi - sqrt_form) < 1e-12

    test gamma_phi_equals_one_over_two_phi_plus_one
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        given gamma_phi = GAMMA_PHI
        and   reciprocal_form = 1.0 / (2.0 * PHI + 1.0)
        then abs(gamma_phi - reciprocal_form) < 1e-12

    test gamma_lqg_standard_value
        // Claim: REFERENCE (LQG standard), tolerance: N/A
        given gamma_1 = GAMMA_LQG_STANDARD
        and   ln2_over_pi_sqrt3 = (2.0_f64.ln()) / (PI * 3.0_f64.sqrt())
        then abs(gamma_1 - ln2_over_pi_sqrt3) < 1e-12

    test gamma_delta_1_phi_percent
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        given delta = DELTA_GAMMA_1_PHI_PERCENT
        then delta > 0.6 and delta < 0.7

    test gamma_delta_2_1_percent
        // Claim: REFERENCE (LQG internal dispute), tolerance: N/A
        given delta = DELTA_GAMMA_2_1_PERCENT
        then delta > 13.0 and delta < 14.5

    test gamma_delta_comparison
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        given delta_1_phi = DELTA_GAMMA_1_PHI_PERCENT
        and   delta_2_1 = DELTA_GAMMA_2_1_PERCENT
        then delta_2_1 > delta_1_phi * 10.0

    test newtons_constant_formula
        // Claim: C-gamma-002 (EMPIRICAL_FIT), tolerance: WITHIN_UNCERTAINTY
        given area_test = 1e6
        and   g_phi = newtons_constant_from_gamma(GAMMA_PHI, PI)
        and   g_1 = newtons_constant_from_gamma(GAMMA_LQG_STANDARD, PI)
        then g_phi > 0.0 and g_1 > 0.0

    test black_hole_entropy_formula
        // Claim: C-gamma-003 (CONJECTURAL), tolerance: CONJECTURAL
        given area = 1.0
        and   s_phi = black_hole_entropy_from_gamma(GAMMA_PHI, area)
        and   s_1 = black_hole_entropy_from_gamma(GAMMA_LQG_STANDARD, area)
        then s_phi > 0.0 and s_1 > 0.0

    test black_hole_shadow_formula
        // Claim: C-gamma-004 (CONJECTURAL), tolerance: CONJECTURAL
        given mass = 1.0
        and   radius = 1.0
        and   theta_phi = black_hole_shadow_from_gamma(GAMMA_PHI, mass, radius)
        and   theta_1 = black_hole_shadow_from_gamma(GAMMA_LQG_STANDARD, mass, radius)
        then theta_phi > 0.0 and theta_1 > 0.0

    test superconductor_tc_sc3_formula
        // Claim: C-gamma-005 (CONJECTURAL), tolerance: CONJECTURAL
        given scale = 1.0
        and   tc_phi = superconductor_tc_sc3(GAMMA_PHI, scale)
        and   tc_1 = superconductor_tc_sc3(GAMMA_LQG_STANDARD, scale)
        then tc_phi > 0.0 and tc_1 > 0.0

    test superconductor_tc_sc4_formula
        // Claim: C-gamma-006 (CONJECTURAL), tolerance: CONJECTURAL
        given scale = 1.0
        and   tc_phi = superconductor_tc_sc4(GAMMA_PHI, scale)
        and   tc_1 = superconductor_tc_sc4(GAMMA_LQG_STANDARD, scale)
        then tc_phi > 0.0 and tc_1 > 0.0

    test gamma_values_are_positive
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        then GAMMA_PHI > 0.0 and GAMMA_LQG_STANDARD > 0.0 and GAMMA_LQG_ALT > 0.0

    test gamma_values_less_than_one
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        then GAMMA_PHI < 1.0 and GAMMA_LQG_STANDARD < 1.0 and GAMMA_LQG_ALT < 1.0

    test gamma_in_expected_range
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        given gamma_phi = GAMMA_PHI
        then gamma_phi > 0.2 and gamma_phi < 0.3

    test verify_gamma_conjecture_report
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        given report = verify_gamma_conjecture(1e6, 1e30, 1e16, 100.0)
        then report.gamma_phi_value > 0.0
        and   report.gamma_1_value > 0.0
        and   report.delta_1_phi > 0.6
        and   report.delta_2_1 > 13.0

    invariant gamma_phi_equals_phi_inverse_cubed
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        assert abs(GAMMA_PHI - pow(PHI, -3.0)) < 1e-15

    invariant gamma_phi_less_than_gamma_lqg_alt
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        assert GAMMA_PHI < GAMMA_LQG_ALT

    invariant delta_gamma_2_1_greater_than_delta_1_phi
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        assert DELTA_GAMMA_2_1_PERCENT > DELTA_GAMMA_1_PHI_PERCENT * 10.0

    invariant gamma_phi_structurally_simple
        // Claim: C-gamma-001 (CONJECTURAL), tolerance: CONJECTURAL
        // gamma_phi = sqrt5 - 2 uses only sqrt5 (from phi) and integer 2
        // gamma_1 = ln(2)/(pisqrt3) uses ln(2), pi, and sqrt3
        given sqrt5_form = 5.0_f64.sqrt() - 2.0
        and   gamma_phi = GAMMA_PHI
        then abs(gamma_phi - sqrt5_form) < 1e-12

    invariant newtons_constant_positive
        // Claim: C-gamma-002 (EMPIRICAL_FIT), tolerance: WITHIN_UNCERTAINTY
        assert newtons_constant_from_gamma(GAMMA_PHI, PI) > 0.0

    invariant black_hole_entropy_positive
        // Claim: C-gamma-003 (CONJECTURAL), tolerance: CONJECTURAL
        given area = 1.0
        assert black_hole_entropy_from_gamma(GAMMA_PHI, area) > 0.0

    invariant black_hole_shadow_positive
        // Claim: C-gamma-004 (CONJECTURAL), tolerance: CONJECTURAL
        given mass = 1.0 and radius = 1.0
        assert black_hole_shadow_from_gamma(GAMMA_PHI, mass, radius) > 0.0

    invariant superconductor_tc_sc3_positive
        // Claim: C-gamma-005 (CONJECTURAL), tolerance: CONJECTURAL
        given scale = 1.0
        assert superconductor_tc_sc3(GAMMA_PHI, scale) > 0.0

    invariant superconductor_tc_sc4_positive
        // Claim: C-gamma-006 (CONJECTURAL), tolerance: CONJECTURAL
        given scale = 1.0
        assert superconductor_tc_sc4(GAMMA_PHI, scale) > 0.0

    bench gamma_conjecture_verification_time
        measure: nanoseconds to compute verify_gamma_conjecture(1e6, 1e30, 1e16, 100.0)
        target: < 2000ns

    bench newtons_constant_computation_time
        measure: nanoseconds to compute newtons_constant_from_gamma(GAMMA_PHI, PI)
        target: < 500ns

    bench black_hole_entropy_computation_time
        measure: nanoseconds to compute black_hole_entropy_from_gamma(GAMMA_PHI, 1e6)
        target: < 200ns

    bench black_hole_shadow_computation_time
        measure: nanoseconds to compute black_hole_shadow_from_gamma(GAMMA_PHI, 1e30, 1e16)
        target: < 300ns
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/axi4.t27
// AXI4-Lite and AXI4-Full Bus Interface Specification for Trinity T27 FPGA HIR
// Defines bus port groups for AW/AR/W/R/B channels
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module Axi4 {

    // === Bus kind ===

    pub const AxiKind = enum(i8) {
        axi4_lite = 0,
        axi4_full = 1,
    }

    // === AXI4 channel signals (described as flat arrays) ===

    pub const MAX_BUS_PORTS : u32 = 32;
    pub const AXI_ADDR_WIDTH : u32 = 32;
    pub const AXI_DATA_WIDTH : u32 = 32;
    pub const AXI_STRB_WIDTH : u32 = 4;
    pub const AXI_ID_WIDTH : u32 = 4;
    pub const AXI_LEN_WIDTH : u32 = 8;
    pub const AXI_SIZE_WIDTH : u32 = 3;
    pub const AXI_BURST_WIDTH : u32 = 2;
    pub const AXI_RESP_WIDTH : u32 = 2;
    pub const AXI_CACHE_WIDTH : u32 = 4;
    pub const AXI_PROT_WIDTH : u32 = 3;
    pub const AXI_QOS_WIDTH : u32 = 4;
    pub const AXI_REGION_WIDTH : u32 = 4;
    pub const AXI_USER_WIDTH : u32 = 1;

    // === Bus port configuration ===

    pub struct AxiBusConfig {
        name : &str,
        kind : i8,
        addr_width : u32,
        data_width : u32,
        id_width : u32,
        has_region : bool,
        has_cache : bool,
        has_prot : bool,
        has_qos : bool,
        has_user : bool,
        has_lock : bool,
    }

    // === Bus port group (flat) ===

    pub struct BusPort {
        name : &str,
        direction : i8,
        width : u32,
        channel : i8,
    }

    // Channel codes
    pub const CH_AW : i8 = 0;
    pub const CH_AR : i8 = 1;
    pub const CH_W : i8 = 2;
    pub const CH_R : i8 = 3;
    pub const CH_B : i8 = 4;

    // === Constructor helpers ===

    fn axi4_lite_slave(name: &str, addr_width: u32, data_width: u32) -> AxiBusConfig {
        return AxiBusConfig{
            .name = name,
            .kind = 0,
            .addr_width = addr_width,
            .data_width = data_width,
            .id_width = 0,
            .has_region = false,
            .has_cache = false,
            .has_prot = true,
            .has_qos = false,
            .has_user = false,
            .has_lock = false,
        };
    }

    fn axi4_lite_master(name: &str, addr_width: u32, data_width: u32) -> AxiBusConfig {
        return AxiBusConfig{
            .name = name,
            .kind = 0,
            .addr_width = addr_width,
            .data_width = data_width,
            .id_width = 0,
            .has_region = false,
            .has_cache = false,
            .has_prot = true,
            .has_qos = false,
            .has_user = false,
            .has_lock = false,
        };
    }

    fn axi4_full_slave(name: &str, addr_width: u32, data_width: u32, id_width: u32) -> AxiBusConfig {
        return AxiBusConfig{
            .name = name,
            .kind = 1,
            .addr_width = addr_width,
            .data_width = data_width,
            .id_width = id_width,
            .has_region = true,
            .has_cache = true,
            .has_prot = true,
            .has_qos = true,
            .has_user = false,
            .has_lock = true,
        };
    }

    fn axi4_full_master(name: &str, addr_width: u32, data_width: u32, id_width: u32) -> AxiBusConfig {
        return AxiBusConfig{
            .name = name,
            .kind = 1,
            .addr_width = addr_width,
            .data_width = data_width,
            .id_width = id_width,
            .has_region = true,
            .has_cache = true,
            .has_prot = true,
            .has_qos = true,
            .has_user = false,
            .has_lock = true,
        };
    }

    // === Query functions ===

    fn is_lite(cfg: AxiBusConfig) -> bool {
        return cfg.kind == 0;
    }

    fn is_full(cfg: AxiBusConfig) -> bool {
        return cfg.kind == 1;
    }

    fn strb_width(cfg: AxiBusConfig) -> u32 {
        return cfg.data_width / 8;
    }

    fn is_master(cfg: AxiBusConfig) -> bool {
        return true;
    }

    // === Port count calculation ===

    fn slave_port_count(cfg: AxiBusConfig) -> u32 {
        var count : u32 = 0;
        // AW channel inputs
        count = count + 1;
        if cfg.id_width > 0 {
            count = count + 1;
        }
        count = count + 1;
        count = count + 1;
        if cfg.has_cache {
            count = count + 1;
        }
        if cfg.has_prot {
            count = count + 1;
        }
        if cfg.has_qos {
            count = count + 1;
        }
        if cfg.has_region {
            count = count + 1;
        }
        if cfg.has_lock {
            count = count + 1;
        }
        // AWREADY output
        count = count + 1;
        // W channel
        count = count + 1;
        count = count + 1;
        // WREADY output
        count = count + 1;
        // B channel
        count = count + 1;
        // BRESP output
        count = count + 1;
        if cfg.id_width > 0 {
            count = count + 1;
        }
        // BREADY input
        count = count + 1;
        // AR channel inputs
        count = count + 1;
        if cfg.id_width > 0 {
            count = count + 1;
        }
        count = count + 1;
        count = count + 1;
        if cfg.has_cache {
            count = count + 1;
        }
        if cfg.has_prot {
            count = count + 1;
        }
        if cfg.has_qos {
            count = count + 1;
        }
        if cfg.has_region {
            count = count + 1;
        }
        if cfg.has_lock {
            count = count + 1;
        }
        // ARREADY output
        count = count + 1;
        // R channel outputs
        count = count + 1;
        count = count + 1;
        if cfg.id_width > 0 {
            count = count + 1;
        }
        // RREADY input
        count = count + 1;
        return count;
    }

    fn total_bus_bits(cfg: AxiBusConfig) -> u32 {
        var bits : u32 = 0;
        bits = bits + cfg.addr_width;
        bits = bits + cfg.data_width;
        bits = bits + cfg.data_width / 8;
        bits = bits + 2;
        bits = bits + 2;
        if cfg.id_width > 0 {
            bits = bits + cfg.id_width * 3;
        }
        if cfg.has_cache {
            bits = bits + 4 * 2;
        }
        if cfg.has_prot {
            bits = bits + 3 * 2;
        }
        if cfg.has_qos {
            bits = bits + 4 * 2;
        }
        if cfg.has_region {
            bits = bits + 4 * 2;
        }
        if cfg.has_lock {
            bits = bits + 2;
        }
        bits = bits + 8;
        bits = bits + 3;
        bits = bits + 2;
        bits = bits + 8;
        return bits;
    }

    // === Validation ===

    fn validate_axi(cfg: AxiBusConfig) -> u32 {
        var errors : u32 = 0;
        if (cfg.name == "") {
            errors = errors + 1;
        }
        if (cfg.addr_width == 0) {
            errors = errors + 1;
        }
        if (cfg.data_width == 0) {
            errors = errors + 1;
        }
        if (cfg.data_width % 8 != 0) {
            errors = errors + 1;
        }
        if (cfg.kind == 1 and cfg.id_width == 0) {
            errors = errors + 1;
        }
        return errors;
    }

    // === Tests ===

    test axi4_lite_is_lite
        given cfg = axi4_lite_slave("s0", 32, 32)
        then is_lite(cfg) == true
        and is_full(cfg) == false

    test axi4_full_is_full
        given cfg = axi4_full_slave("s1", 32, 64, 4)
        then is_full(cfg) == true
        and is_lite(cfg) == false

    test strb_width_32bit
        given cfg = axi4_lite_slave("s0", 32, 32)
        then strb_width(cfg) == 4

    test strb_width_64bit
        given cfg = axi4_full_slave("s1", 32, 64, 4)
        then strb_width(cfg) == 8

    test validate_lite_ok
        given cfg = axi4_lite_slave("s0", 32, 32)
        then validate_axi(cfg) == 0

    test validate_full_ok
        given cfg = axi4_full_slave("s1", 32, 64, 4)
        then validate_axi(cfg) == 0

    test validate_empty_name
        given cfg = axi4_lite_slave("", 32, 32)
        then validate_axi(cfg) > 0

    test validate_zero_addr
        given cfg = axi4_lite_slave("s0", 0, 32)
        then validate_axi(cfg) > 0

    test validate_zero_data
        given cfg = axi4_lite_slave("s0", 32, 0)
        then validate_axi(cfg) > 0

    test validate_non_byte_data
        given cfg = AxiBusConfig{.name = "s0", .kind = 0, .addr_width = 32, .data_width = 12, .id_width = 0, .has_region = false, .has_cache = false, .has_prot = true, .has_qos = false, .has_user = false, .has_lock = false}
        then validate_axi(cfg) > 0

    test validate_full_no_id
        given cfg = axi4_full_slave("s1", 32, 32, 0)
        then validate_axi(cfg) > 0

    test slave_port_count_lite
        given cfg = axi4_lite_slave("s0", 32, 32)
        then slave_port_count(cfg) > 0

    test total_bus_bits_positive
        given cfg = axi4_lite_slave("s0", 32, 32)
        then total_bus_bits(cfg) > 0

    test lite_no_id
        given cfg = axi4_lite_slave("s0", 32, 32)
        then cfg.id_width == 0

    test full_has_id
        given cfg = axi4_full_slave("s1", 32, 64, 4)
        then cfg.id_width == 4

    test full_has_extras
        given cfg = axi4_full_slave("s1", 32, 64, 4)
        then cfg.has_cache == true
        and cfg.has_region == true
        and cfg.has_qos == true
        and cfg.has_lock == true

    // === Invariants ===

    invariant addr_width_positive
        given cfg = axi4_lite_slave("inv", 32, 32)
        assert cfg.addr_width > 0

    invariant data_width_byte_aligned
        given cfg = axi4_lite_slave("inv", 32, 32)
        assert cfg.data_width % 8 == 0

    invariant strb_width_matches_data
        given cfg = axi4_lite_slave("inv", 32, 32)
        assert strb_width(cfg) == cfg.data_width / 8

    invariant lite_has_zero_id
        given cfg = axi4_lite_slave("inv", 32, 32)
        assert cfg.id_width == 0

    invariant full_has_nonzero_id
        given cfg = axi4_full_slave("inv", 32, 32, 4)
        assert cfg.id_width > 0

    invariant validate_non_negative
        given cfg = axi4_lite_slave("inv", 32, 32)
        assert validate_axi(cfg) >= 0

    invariant total_bus_bits_positive
        given cfg = axi4_lite_slave("inv", 32, 32)
        assert total_bus_bits(cfg) > 0

    // === Benchmarks ===

    bench validate_latency
        measure: nanoseconds to validate_axi(axi4_lite_slave("b", 32, 32))
        target: < 100ns

    bench port_count_latency
        measure: nanoseconds to slave_port_count(axi4_full_slave("b", 32, 64, 4))
        target: < 200ns
}

// phi^2 + 1/phi^2 = 3 | TRINITY

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/assembler.t27
// T27 Ternary Assembler Specification
// High-level assembler for the ternary ISA, compiles to machine code
// Supports R-type, I-type, and GF16 extended instructions
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module Assembler {

    // === Assembler section kind ===

    pub const SectionKind = enum(i8) {
        text = 0,
        data = 1,
        bss = 2,
        rodata = 3,
    }

    // === Relocation kind ===

    pub const RelocKind = enum(i8) {
        abs32 = 0,
        rel21 = 1,
        gf16_label = 2,
    }

    // === Assembled instruction ===

    pub struct AssembledInstr {
        address : u32,
        opcode : u32,
        rd : u32,
        rs1 : u32,
        rs2 : u32,
        imm : u32,
        label : &str,
        is_gf16 : bool,
    }

    // === Relocation entry ===

    pub struct RelocEntry {
        offset : u32,
        kind : i8,
        symbol : &str,
        addend : u32,
    }

    // === Symbol table entry ===

    pub struct Symbol {
        name : &str,
        address : u32,
        size : u32,
        section : i8,
        is_global : bool,
    }

    // === Assembler section ===

    pub struct AsmSection {
        name : &str,
        kind : i8,
        base_address : u32,
        size : u32,
    }

    // === Assembler config ===

    pub struct AsmConfig {
        name : &str,
        text_base : u32,
        data_base : u32,
        word_size : u32,
        has_gf16_ext : bool,
        has_ternary_ext : bool,
    }

    // === Constructor helpers ===

    fn asm_config(name: &str) -> AsmConfig {
        return AsmConfig{
            .name = name,
            .text_base = 0,
            .data_base = 4096,
            .word_size = 4,
            .has_gf16_ext = true,
            .has_ternary_ext = true,
        };
    }

    fn text_section(base: u32) -> AsmSection {
        return AsmSection{
            .name = ".text",
            .kind = 0,
            .base_address = base,
            .size = 0,
        };
    }

    fn data_section(base: u32) -> AsmSection {
        return AsmSection{
            .name = ".data",
            .kind = 1,
            .base_address = base,
            .size = 0,
        };
    }

    fn r_instruction(opcode: u32, rd: u32, rs1: u32, rs2: u32) -> AssembledInstr {
        return AssembledInstr{
            .address = 0,
            .opcode = opcode,
            .rd = rd,
            .rs1 = rs1,
            .rs2 = rs2,
            .imm = 0,
            .label = "",
            .is_gf16 = false,
        };
    }

    fn i_instruction(opcode: u32, rd: u32, rs1: u32, imm: u32) -> AssembledInstr {
        return AssembledInstr{
            .address = 0,
            .opcode = opcode,
            .rd = rd,
            .rs1 = rs1,
            .rs2 = 0,
            .imm = imm,
            .label = "",
            .is_gf16 = false,
        };
    }

    fn gf16_instruction(opcode: u32, rd: u32, rs1: u32, rs2: u32) -> AssembledInstr {
        return AssembledInstr{
            .address = 0,
            .opcode = opcode,
            .rd = rd,
            .rs1 = rs1,
            .rs2 = rs2,
            .imm = 0,
            .label = "",
            .is_gf16 = true,
        };
    }

    fn symbol(name: &str, address: u32, section: i8, is_global: bool) -> Symbol {
        return Symbol{
            .name = name,
            .address = address,
            .size = 0,
            .section = section,
            .is_global = is_global,
        };
    }

    fn reloc(offset: u32, kind: i8, symbol_name: &str, addend: u32) -> RelocEntry {
        return RelocEntry{
            .offset = offset,
            .kind = kind,
            .symbol = symbol_name,
            .addend = addend,
        };
    }

    // === Query functions ===

    fn is_r_type(instr: AssembledInstr) -> bool {
        return instr.imm == 0 and instr.rs2 > 0;
    }

    fn is_i_type(instr: AssembledInstr) -> bool {
        return instr.imm > 0;
    }

    fn is_gf16_instr(instr: AssembledInstr) -> bool {
        return instr.is_gf16;
    }

    fn encode_r_type(instr: AssembledInstr) -> u32 {
        return (instr.opcode << 26) | (instr.rd << 21) | (instr.rs1 << 16) | (instr.rs2 << 11);
    }

    fn encode_i_type(instr: AssembledInstr) -> u32 {
        return (instr.opcode << 26) | (instr.rd << 21) | (instr.rs1 << 16) | (instr.imm & 65535);
    }

    fn section_end(sec: AsmSection) -> u32 {
        return sec.base_address + sec.size;
    }

    fn align_address(addr: u32, alignment: u32) -> u32 {
        if (alignment == 0) {
            return addr;
        }
        var remainder : u32 = addr % alignment;
        if (remainder == 0) {
            return addr;
        }
        return addr + alignment - remainder;
    }

    fn instr_count(cfg: AsmConfig, bytes: u32) -> u32 {
        if (cfg.word_size == 0) {
            return 0;
        }
        return bytes / cfg.word_size;
    }

    // === Validation ===

    fn validate_config(cfg: AsmConfig) -> u32 {
        var errors : u32 = 0;
        if (cfg.name == "") {
            errors = errors + 1;
        }
        if (cfg.word_size == 0) {
            errors = errors + 1;
        }
        return errors;
    }

    fn validate_symbol(sym: Symbol) -> u32 {
        var errors : u32 = 0;
        if (sym.name == "") {
            errors = errors + 1;
        }
        return errors;
    }

    // === Tests ===

    test asm_config_creation
        given cfg = asm_config("t27_asm")
        then cfg.text_base == 0
        and cfg.data_base == 4096
        and cfg.word_size == 4
        and cfg.has_gf16_ext == true
        and cfg.has_ternary_ext == true

    test text_section_creation
        given sec = text_section(0)
        then sec.kind == 0
        and sec.base_address == 0

    test data_section_creation
        given sec = data_section(4096)
        then sec.kind == 1
        and sec.base_address == 4096

    test r_instruction_creation
        given instr = r_instruction(1, 5, 6, 7)
        then is_r_type(instr) == true
        and is_i_type(instr) == false
        and is_gf16_instr(instr) == false

    test i_instruction_creation
        given instr = i_instruction(2, 5, 6, 42)
        then is_i_type(instr) == true
        and is_r_type(instr) == false

    test gf16_instruction_creation
        given instr = gf16_instruction(16, 5, 6, 7)
        then is_gf16_instr(instr) == true
        and is_r_type(instr) == true

    test encode_r_type
        given instr = r_instruction(1, 5, 6, 7)
        then encode_r_type(instr) > 0

    test encode_i_type
        given instr = i_instruction(2, 5, 6, 42)
        then encode_i_type(instr) > 0

    test section_end
        given sec = AsmSection{.name = ".text", .kind = 0, .base_address = 0, .size = 128}
        then section_end(sec) == 128

    test align_address_zero
        then align_address(5, 4) == 8

    test align_address_already_aligned
        then align_address(8, 4) == 8

    test align_address_zero_alignment
        then align_address(5, 0) == 5

    test instr_count
        given cfg = asm_config("test")
        then instr_count(cfg, 128) == 32

    test symbol_creation
        given sym = symbol("main", 0, 0, true)
        then sym.name == "main"
        and sym.is_global == true

    test reloc_creation
        given r = reloc(64, 0, "data_start", 0)
        then r.offset == 64
        and r.symbol == "data_start"

    test validate_config_ok
        given cfg = asm_config("test")
        then validate_config(cfg) == 0

    test validate_config_empty_name
        given cfg = AsmConfig{.name = "", .text_base = 0, .data_base = 4096, .word_size = 4, .has_gf16_ext = true, .has_ternary_ext = true}
        then validate_config(cfg) > 0

    test validate_symbol_ok
        given sym = symbol("main", 0, 0, true)
        then validate_symbol(sym) == 0

    test validate_symbol_empty_name
        given sym = symbol("", 0, 0, true)
        then validate_symbol(sym) > 0

    // === Invariants ===

    invariant word_size_positive
        given cfg = asm_config("inv")
        assert cfg.word_size > 0

    invariant data_base_above_text
        given cfg = asm_config("inv")
        assert cfg.data_base >= cfg.text_base

    invariant align_never_decreases
        given a = align_address(100, 16)
        assert a >= 100

    invariant validate_non_negative
        given cfg = asm_config("inv")
        assert validate_config(cfg) >= 0

    // === Benchmarks ===

    bench encode_latency
        measure: nanoseconds for encode_r_type(r_instruction(1, 5, 6, 7))
        target: < 100ns
}

// phi^2 + 1/phi^2 = 3 | TRINITY

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/power.t27
// T27 Power Estimation Specification
// Estimates dynamic and static power consumption for FPGA designs
// Artix-7 power model: LUT=10uW/MHz, FF=5uW/MHz, BRAM=50uW/MHz, DSP=100uW/MHz
// Static: 50mW base + 0.1uW per resource unit
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module Power {

    // === Power domain ===

    pub struct PowerDomain {
        name : &str,
        voltage_mv : u32,
        clock_mhz : u32,
        toggle_rate : u32,
    }

    fn power_domain(name: &str, clock_mhz: u32) -> PowerDomain {
        return PowerDomain{
            .name = name,
            .voltage_mv = 1000,
            .clock_mhz = clock_mhz,
            .toggle_rate = 12,
        };
    }

    // === Power constants ===

    fn lut_power_uw_per_mhz() -> u32 {
        return 10;
    }

    fn ff_power_uw_per_mhz() -> u32 {
        return 5;
    }

    fn bram_power_uw_per_mhz() -> u32 {
        return 50;
    }

    fn dsp_power_uw_per_mhz() -> u32 {
        return 100;
    }

    fn io_power_uw_per_mhz() -> u32 {
        return 20;
    }

    fn static_base_mw() -> u32 {
        return 50;
    }

    fn static_per_resource_uw() -> u32 {
        return 100;
    }

    // === Power estimate ===

    pub struct PowerEstimate {
        dynamic_mw : u32,
        static_mw : u32,
        total_mw : u32,
        lut_power_uw : u32,
        ff_power_uw : u32,
        bram_power_uw : u32,
        dsp_power_uw : u32,
    }

    fn power_estimate(dynamic: u32, static_p: u32) -> PowerEstimate {
        return PowerEstimate{
            .dynamic_mw = dynamic,
            .static_mw = static_p,
            .total_mw = dynamic + static_p,
            .lut_power_uw = 0,
            .ff_power_uw = 0,
            .bram_power_uw = 0,
            .dsp_power_uw = 0,
        };
    }

    fn zero_power() -> PowerEstimate {
        return power_estimate(0, 0);
    }

    // === Estimation functions ===

    fn est_lut_dynamic(luts: u32, clock_mhz: u32, toggle_rate: u32) -> u32 {
        return luts * lut_power_uw_per_mhz() * clock_mhz * toggle_rate / 1000 / 100;
    }

    fn est_ff_dynamic(ffs: u32, clock_mhz: u32, toggle_rate: u32) -> u32 {
        return ffs * ff_power_uw_per_mhz() * clock_mhz * toggle_rate / 1000 / 100;
    }

    fn est_bram_dynamic(brams: u32, clock_mhz: u32) -> u32 {
        return brams * bram_power_uw_per_mhz() * clock_mhz / 1000;
    }

    fn est_dsp_dynamic(dsps: u32, clock_mhz: u32) -> u32 {
        return dsps * dsp_power_uw_per_mhz() * clock_mhz / 1000;
    }

    fn est_static(total_resources: u32) -> u32 {
        return static_base_mw() + total_resources * static_per_resource_uw() / 1000;
    }

    fn total_resources(luts: u32, ffs: u32, brams: u32, dsps: u32) -> u32 {
        return luts + ffs + brams + dsps;
    }

    fn est_total_power(luts: u32, ffs: u32, brams: u32, dsps: u32, clock_mhz: u32, toggle_rate: u32) -> PowerEstimate {
        var lut_p = est_lut_dynamic(luts, clock_mhz, toggle_rate);
        var ff_p = est_ff_dynamic(ffs, clock_mhz, toggle_rate);
        var bram_p = est_bram_dynamic(brams, clock_mhz);
        var dsp_p = est_dsp_dynamic(dsps, clock_mhz);
        var dyn = lut_p + ff_p + bram_p + dsp_p;
        var stat = est_static(total_resources(luts, ffs, brams, dsps));
        return PowerEstimate{
            .dynamic_mw = dyn,
            .static_mw = stat,
            .total_mw = dyn + stat,
            .lut_power_uw = lut_p,
            .ff_power_uw = ff_p,
            .bram_power_uw = bram_p,
            .dsp_power_uw = dsp_p,
        };
    }

    // === Validation ===

    fn validate_domain(d: PowerDomain) -> u32 {
        var errors : u32 = 0;
        if d.name == "" {
            errors = errors + 1;
        }
        if d.clock_mhz == 0 {
            errors = errors + 1;
        }
        return errors;
    }

    // === Tests ===

    test power_domain_creation
        given d = power_domain("core", 100)
        then d.name == "core"
        and d.voltage_mv == 1000
        and d.clock_mhz == 100
        and d.toggle_rate == 12

    test zero_power
        given p = zero_power()
        then p.dynamic_mw == 0
        and p.static_mw == 0
        and p.total_mw == 0

    test power_estimate_creation
        given p = power_estimate(200, 100)
        then p.dynamic_mw == 200
        and p.static_mw == 100
        and p.total_mw == 300

    test est_lut_dynamic
        then est_lut_dynamic(1000, 100, 12) > 0

    test est_ff_dynamic
        then est_ff_dynamic(2000, 100, 12) > 0

    test est_bram_dynamic
        then est_bram_dynamic(10, 100) == 50

    test est_dsp_dynamic
        then est_dsp_dynamic(8, 100) == 80

    test est_static
        then est_static(5000) > static_base_mw()

    test est_static_base
        then est_static(0) == static_base_mw()

    test total_resources_calc
        then total_resources(1000, 2000, 10, 8) == 3018

    test est_total_power_arty
        given p = est_total_power(15000, 30000, 30, 50, 100, 12)
        then p.dynamic_mw > 0
        and p.static_mw > 0
        and p.total_mw > p.dynamic_mw
        and p.total_mw > p.static_mw

    test power_constants
        then lut_power_uw_per_mhz() == 10
        and ff_power_uw_per_mhz() == 5
        and bram_power_uw_per_mhz() == 50
        and dsp_power_uw_per_mhz() == 100
        and static_base_mw() == 50

    test validate_domain_ok
        given d = power_domain("core", 100)
        then validate_domain(d) == 0

    test validate_domain_empty
        given d = PowerDomain{.name = "", .voltage_mv = 1000, .clock_mhz = 100, .toggle_rate = 12}
        then validate_domain(d) > 0

    test validate_domain_zero_clock
        given d = PowerDomain{.name = "core", .voltage_mv = 1000, .clock_mhz = 0, .toggle_rate = 12}
        then validate_domain(d) > 0

    // === Invariants ===

    invariant power_non_negative
        given p = zero_power()
        assert p.total_mw >= 0

    invariant static_base_positive
        assert static_base_mw() > 0

    // === Benchmarks ===

    bench power_est_latency
        measure: nanoseconds for est_total_power(15000, 30000, 30, 50, 100, 12)
        target: < 100ns
}

// phi^2 + 1/phi^2 = 3 | TRINITY

// SPDX-License-Identifier: Apache-2.0
// Formula Discovery v1.0 — ULTRA ENGINE Specification
// φ² + 1/φ² = 3 | TRINITY

module FormulaDiscovery {
    use math::constants;

    // ===== Sacred Constants =====
    const PHI: f64 = 1.6180339887498948;
    const PI: f64 = 3.1415926535897932;
    const E: f64 = 2.7182818284590452;

    // ===== Discovery Methods =====

    // Base formulas from formula_registry.t27 for chimera search
    // These serve as parent formulas for discovery operations
    const S1_gamma: f64 = pow(PHI, -3.0);
    const PM1b_alpha_inv_exact: f64 = (360.0 / pow(PHI, 2.0)) - 2.0 / pow(PHI, 3.0) + 1.0 / pow(3.0 * PHI, 5.0);
    const N1_alpha_s: f64 = 1.0 / (pow(PHI, 4.0) + PHI);
    const N2_Tc: f64 = 156.5;
    const CKM1_theta_C: f64 = (360.0 / pow(PHI, 2.0)) / 16.0;
    const CKM2_V_cb: f64 = 1.0 / (7.0 * pow(PHI, 2.0) * pow(PI, 2.0) * pow(E, 2.0));
    const PMNS2_sin2th23: f64 = 3.0 * pow(PHI, -8.0) * PI * E;
    const PMNS3_delta_CP: f64 = 9.0 * pow(PHI, -2.0) * 180.0 / PI;
    const PMNS4_sin2th12: f64 = 4.0 / (pow(PHI, 2.0) * pow(PI, 4.0) * pow(E, 4.0));
    const H1_mH_mZ: f64 = (1.0 / 8.0) * pow(PHI, 2.0) * pow(PI, 3.0) * pow(E, -2.0);

    // Chimera v07 formulas
    const P10_V_ud: f64 = 7.0 * pow(PHI, -5.0) * pow(PI, 3.0) * pow(E, -3.0);
    const P11_V_cs: f64 = 7.0 * pow(PHI, -5.0) * pow(PI, 3.0) * pow(E, -3.0);
    const P12_V_td: f64 = 2.0 * pow(PHI, -4.0) * pow(PI, -4.0) * E;
    const P13_sin2th12_chimera: f64 = 8.0 * pow(PHI, -5.0) * PI * pow(E, -2.0);
    const P14_delta_CP_rad: f64 = 9.0 * pow(PHI, -2.0);
    const P15_ms_mmu: f64 = pow(PHI, -2.0) / PI * pow(E, 2.0);
    const P16_mb_mt: f64 = 4.0 * pow(PHI, -2.0) / PI * pow(E, -3.0);
    const P17_Omega_b: f64 = 4.0 * pow(PHI, -2.0) * pow(PI, -3.0);
    const P18_ns: f64 = 3.0 * pow(PHI, 3.0) * pow(PI, -4.0) * pow(E, 2.0);

    // ===== Chimera Search Functions =====

    /// Combine two formulas with arithmetic operations
    fn chimera_mul(a: f64, b: f64) -> f64 {
        return a * b;
    }

    fn chimera_div(a: f64, b: f64) -> f64 {
        if abs(b) < 1e-15 {
            return 0.0;
        }
        return a / b;
    }

    fn chimera_add(a: f64, b: f64) -> f64 {
        return a + b;
    }

    fn chimera_sub(a: f64, b: f64) -> f64 {
        return a - b;
    }

    // ===== Trigonometric Functions =====

    fn chimera_sin(x: f64) -> f64 {
        return sin(x);
    }

    fn chimera_cos(x: f64) -> f64 {
        return cos(x);
    }

    // ===== Logarithmic and Exponential Functions =====

    fn chimera_ln(x: f64) -> f64 {
        if x <= 0.0 {
            return 0.0;
        }
        return ln(x);
    }

    fn chimera_exp(x: f64) -> f64 {
        return exp(x);
    }

    // ===== Power Function =====

    fn chimera_pow(x: f64, n: f64) -> f64 {
        return powf(x, n);
    }

    // ===== Pattern Generation =====

    /// Generate n·φⁱ·πʲ·eᵏ patterns
    fn generate_basis(max_pow: i32) -> Vec<(String, f64)> {
        let mut basis = Vec::new();

        for i in -max_pow..=max_pow {
            for j in -max_pow..=max_pow {
                for k in -max_pow..=max_pow {
                    let val = 1.0_f64 * powi(PHI, i) * powi(PI, j) * powi(E, k);
                    basis.push((format!("φ^{}π^{}e^{}", i, j, k), val));
                }
            }
        }

        basis
    }

    // ===== Tests =====

    test "S1_gamma_verified" {
        given g = S1_gamma
        and   pdg = 0.23607
        when  err = abs(g - pdg) / pdg
        then  err < 0.001
    }

    test "N1_alpha_s_verified" {
        given as = N1_alpha_s
        and   pdg = 0.118034
        when  err = abs(as - pdg) / pdg
        then  err < 0.001
    }

    test "PMNS2_sin2th23_verified" {
        given s = PMNS2_sin2th23
        and   pdg = 0.547
        when  err = abs(s - pdg) / pdg
        then  err < 0.001
    }

    test "trinity_identity" {
        given t = pow(PHI, 2.0) + 1.0 / pow(PHI, 2.0)
        then  abs(t - 3.0) < 1e-12
    }

    // ===== Invariants =====

    invariant "phi_positive" {
        assert PHI > 1.5 and PHI < 1.7
    }

    invariant "gamma_positive" {
        assert S1_gamma > 0.0 and S1_gamma < 1.0
    }

    invariant "sin2th23_in_bounds" {
        let s = PMNS2_sin2th23;
        assert s > 0.0 and s < 1.0
    }

    invariant "ckm_unitarity_check" {
        let v_us = 1.0 / (E * PHI);
        let v_cb = CKM2_V_cb;
        let v_ud = P10_V_ud;
        assert v_us > 0.0 and v_cb > 0.0 and v_ud > 0.0 and v_ud < 1.0
    }
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/bootrom.t27
// T27 Boot ROM Specification
// Boot sequence stages, init vectors, integrity checksum
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module BootROM {

    pub struct BootStage {
        name : &str,
        index : u32,
        size_bytes : u32,
        entry_addr : u32,
    }

    fn boot_stage(name: &str, idx: u32, size: u32, entry: u32) -> BootStage {
        return BootStage{
            .name = name,
            .index = idx,
            .size_bytes = size,
            .entry_addr = entry,
        };
    }

    fn stage_end(s: BootStage) -> u32 {
        return s.entry_addr + s.size_bytes;
    }

    pub struct BootConfig {
        name : &str,
        rom_base : u32,
        rom_size : u32,
        has_integrity_check : bool,
        has_chain_loader : bool,
    }

    fn boot_config(name: &str, rom_size: u32) -> BootConfig {
        return BootConfig{
            .name = name,
            .rom_base = 0,
            .rom_size = rom_size,
            .has_integrity_check = true,
            .has_chain_loader = true,
        };
    }

    fn validate_config(cfg: BootConfig) -> u32 {
        var errors : u32 = 0;
        if cfg.name == "" { errors = errors + 1; }
        if cfg.rom_size == 0 { errors = errors + 1; }
        return errors;
    }

    fn config_end(cfg: BootConfig) -> u32 {
        return cfg.rom_base + cfg.rom_size;
    }

    fn fits(cfg: BootConfig, stages: [BootStage], count: u32) -> bool {
        var total : u32 = 0;
        var i : u32 = 0;
        while i < count {
            total = total + stages[i].size_bytes;
            i = i + 1;
        }
        return total <= cfg.rom_size;
    }

    // === Tests ===

    test boot_stage_creation
        given s = boot_stage("fsbl", 0, 4096, 0)
        then s.name == "fsbl"
        and s.index == 0
        and stage_end(s) == 4096

    test boot_config_creation
        given c = boot_config("trinity_boot", 32768)
        then c.rom_size == 32768
        and c.has_integrity_check == true
        and config_end(c) == 32768

    test validate_config_ok
        given c = boot_config("ok", 4096)
        then validate_config(c) == 0

    test validate_config_empty
        given c = BootConfig{.name = "", .rom_base = 0, .rom_size = 0, .has_integrity_check = true, .has_chain_loader = true}
        then validate_config(c) > 0

    test fits_yes
        given c = boot_config("test", 8192)
        and s1 = boot_stage("s1", 0, 4096, 0)
        and s2 = boot_stage("s2", 1, 2048, 4096)
        then fits(c, [s1, s2], 2) == true

    test fits_no
        given c = boot_config("test", 1024)
        and s1 = boot_stage("s1", 0, 4096, 0)
        then fits(c, [s1], 1) == false

    test stage_end_nonzero
        given s = boot_stage("app", 2, 8192, 0x1000)
        then stage_end(s) == 0x1000 + 8192

    test fits_exact
        given c = boot_config("exact", 4096)
        and s1 = boot_stage("s1", 0, 4096, 0)
