// SPDX-License-Identifier: Apache-2.0
// t27/specs/isa/ternary_control_flow.t27
// Ternary Control Flow Specification
// Ring 090 - Control flow operations for ternary architecture
// Conditional jumps, branches, and call/return
// phi^2 + 1/phi^2 = 3 | TRINITY

module TernaryControlFlow {
    use base::types;

    // =================================================================
    // 1. Branch Conditions
    // =========================================================================

    // Trit values for condition evaluation
    const TRIT_NEG : i32 = -1;
    const TRIT_ZERO : i32 = 0;
    const TRIT_POS : i32 = 1;

    // Condition codes
    const COND_EQ : u8 = 0;    // Equal to zero
    const COND_NE : u8 = 1;    // Not equal to zero
    const COND_POS : u8 = 2;   // Positive
    const COND_NEG : u8 = 3;   // Negative
    const COND_NZ : u8 = 4;    // Non-zero
    const COND_NC : u8 = 5;    // No condition (always true)

    // Branch prediction hints
    const PRED_TAKEN : u8 = 0;    // Likely taken
    const PRED_NOT_TAKEN : u8 = 1; // Likely not taken
    const PRED_NONE : u8 = 2;     // No prediction

    // =================================================================
    // 2. Program Counter Operations
    // =========================================================================

    // pc_read() -> u32
    // Read current program counter
    fn pc_read() -> u32 {
        // In real implementation, PC is in register file (R19)
        return 0;  // Placeholder
    }

    // pc_write(addr: u32) -> void
    // Write new program counter (branch/jump)
    fn pc_write(addr: u32) -> void {
        // In real implementation, writes to PC register (R19)
    }

    // pc_relative(offset: i32) -> u32
    // Calculate relative address
    fn pc_relative(offset: i32) -> u32 {
        const current_pc = pc_read();
        return (current_pc as i32 + offset) as u32;
    }

    // =================================================================
    // 3. Conditional Branch Operations
    // =========================================================================

    // branch_cond(value: i32, condition: u8, offset: i32) -> bool
    // Branch if condition matches value
    // Returns true if branch was taken
    fn branch_cond(value: i32, condition: u8, offset: i32) -> bool {
        var should_branch : bool = false;

        if (condition == COND_EQ) {
            should_branch = (value == TRIT_ZERO);
        } else if (condition == COND_NE) {
            should_branch = (value != TRIT_ZERO);
        } else if (condition == COND_POS) {
            should_branch = (value == TRIT_POS);
        } else if (condition == COND_NEG) {
            should_branch = (value == TRIT_NEG);
        } else if (condition == COND_NZ) {
            should_branch = (value != TRIT_ZERO);
        } else if (condition == COND_NC) {
            should_branch = true;
        }

        if (should_branch) {
            pc_write(pc_relative(offset));
            return true;
        }

        return false;
    }

    // branch_if(value: i32, offset: i32) -> bool
    // Branch if value is non-zero (true)
    fn branch_if(value: i32, offset: i32) -> bool {
        return branch_cond(value, COND_NZ, offset);
    }

    // branch_if_not(value: i32, offset: i32) -> bool
    // Branch if value is zero (false)
    fn branch_if_not(value: i32, offset: i32) -> bool {
        return branch_cond(value, COND_EQ, offset);
    }

    // =================================================================
    // 4. Unconditional Branch Operations
    // =========================================================================

    // jump(addr: u32) -> void
    // Unconditional jump to absolute address
    fn jump(addr: u32) -> void {
        pc_write(addr);
    }

    // jump_relative(offset: i32) -> void
    // Unconditional jump to relative address
    fn jump_relative(offset: i32) -> void {
        pc_write(pc_relative(offset));
    }

    // jump_link(addr: u32, link_reg: *u32) -> void
    // Jump and store return address
    fn jump_link(addr: u32, link_reg: *u32) -> void {
        link_reg.* = pc_read();
        pc_write(addr);
    }

    // jump_link_relative(offset: i32, link_reg: *u32) -> void
    // Jump relative and store return address
    fn jump_link_relative(offset: i32, link_reg: *u32) -> void {
        link_reg.* = pc_read();
        jump_relative(offset);
    }

    // =================================================================
    // 5. Return Operation
    // =========================================================================

    // ret(link_reg: u32) -> void
    // Return to address in link register
    fn ret(link_reg: u32) -> void {
        pc_write(link_reg);
    }

    // =================================================================
    // 6. Call/Return with Stack
    // =========================================================================

    // call(addr: u32, sp: *u32, memory: []TernaryWord) -> bool
    // Call subroutine: push return address, then jump
    fn call(addr: u32, sp: *u32, memory: []TernaryWord) -> bool {
        const return_addr = TernaryWord{ .raw = pc_read() };

        // Push return address
        if (sp.* == 0) {
            return false;  // Stack overflow
        }
        sp.* = sp.* - 1;

        if (sp.* >= memory.len()) {
            return false;
        }
        memory[sp.*] = return_addr;

        // Jump to subroutine
        pc_write(addr);
        return true;
    }

    // ret_pop(sp: *u32, memory: []TernaryWord) -> bool
    // Return: pop return address, then jump
    fn ret_pop(sp: *u32, memory: []TernaryWord) -> bool {
        if (sp.* >= memory.len()) {
            return false;
        }

        const return_addr = memory[sp.*];
        sp.* = sp.* + 1;

        // Jump to return address
        pc_write(return_addr.raw);
        return true;
    }

    // =================================================================
    // 7. Compare Operations
    // =========================================================================

    // compare(a: i32, b: i32) -> i32
    // Compare two trit values, return condition code
    // Returns: TRIT_NEG if a < b, TRIT_ZERO if a == b, TRIT_POS if a > b
    fn compare(a: i32, b: i32) -> i32 {
        if (a < b) {
            return TRIT_NEG;
        } else if (a > b) {
            return TRIT_POS;
        } else {
            return TRIT_ZERO;
        }
    }

    // compare_and_branch(a: i32, b: i32, condition: u8, offset: i32) -> bool
    // Compare two values and branch if condition true
    fn compare_and_branch(a: i32, b: i32, condition: u8, offset: i32) -> bool {
        const result = compare(a, b);
        return branch_cond(result, condition, offset);
    }

    // =================================================================
    // 8. Table Branch (Switch)
    // =========================================================================

    // table_branch(index: i32, jump_table: []u32, default_addr: u32) -> void
    // Jump to address in jump_table[index], or default if out of range
    fn table_branch(index: i32, jump_table: []u32, default_addr: u32) -> void {
        if (index < 0 or index >= jump_table.len()) {
            jump(default_addr);
        } else {
            jump(jump_table[index]);
        }
    }

    // =================================================================
    // TDD-Inside-Spec: Tests and Invariants
    // =========================================================================

    test branch_if_taken
        given offset = 10
        and   taken = branch_if(TRIT_POS, offset)
        then taken == true

    test branch_if_not_taken
        given offset = 10
        and   taken = branch_if(TRIT_ZERO, offset)
        then taken == false

    test branch_if_not_taken_zero
        given offset = 10
        and   taken = branch_if_not(TRIT_ZERO, offset)
        then taken == true

    test branch_cond_eq_true
        given offset = 5
        and   taken = branch_cond(TRIT_ZERO, COND_EQ, offset)
        then taken == true

    test branch_cond_eq_false
        given offset = 5
        and   taken = branch_cond(TRIT_POS, COND_EQ, offset)
        then taken == false

    test branch_cond_pos_true
        given offset = 7
        and   taken = branch_cond(TRIT_POS, COND_POS, offset)
        then taken == true

    test branch_cond_neg_true
        given offset = 3
        and   taken = branch_cond(TRIT_NEG, COND_NEG, offset)
        then taken == true

    test branch_cond_nc_always_true
        given offset = 15
        and   taken = branch_cond(TRIT_NEG, COND_NC, offset)
        then taken == true

    test jump_relative_forward
        given offset = 10
        and   pc = pc_relative(offset)
        then pc == 10

    test jump_relative_backward
        given offset = -5
        and   pc = pc_relative(offset)
        then pc == 0xFFFFFFFF  // -5 wrapped

    test compare_less
        given result = compare(TRIT_NEG, TRIT_ZERO)
        then result == TRIT_NEG

    test compare_equal
        given result = compare(TRIT_POS, TRIT_POS)
        then result == TRIT_ZERO

    test compare_greater
        given result = compare(TRIT_POS, TRIT_ZERO)
        then result == TRIT_POS

    test compare_and_branch_less
        given taken = compare_and_branch(TRIT_NEG, TRIT_ZERO, COND_NEG, 5)
        then taken == true

    test compare_and_branch_not_less
        given taken = compare_and_branch(TRIT_POS, TRIT_ZERO, COND_NEG, 5)
        then taken == false

    test table_branch_valid
        given table = []u32{100, 200, 300}
        and   table_branch(1, table, 0)
        // PC should be 200
        then true

    test table_branch_default
        given table = []u32{100, 200, 300}
        and   table_branch(5, table, 999)
        // PC should be 999 (default)
        then true

    test jump_link_saves_return_addr
        given lr : u32 = 0
        and   pc_set_to(50)
        and   jump_link(100, &lr)
        then lr == 50

    test ret_restores_pc
        given lr : u32 = 50
        and   ret(lr)
        // PC should be 50
        then true

    invariant branch_condition_codes_valid
        assert COND_EQ <= 5 and COND_NC <= 5

    invariant branch_prediction_hints_valid
        assert PRED_TAKEN <= 2 and PRED_NOT_TAKEN <= 2

    invariant compare_trichotomous
        given a = TRIT_NEG
        and   b = TRIT_ZERO
        and   c = TRIT_POS
        and   r1 = compare(a, a)
        and   r2 = compare(b, b)
        and   r3 = compare(c, c)
        assert r1 == TRIT_ZERO and r2 == TRIT_ZERO and r3 == TRIT_ZERO

    invariant compare_less_greater_antisymmetric
        given r1 = compare(TRIT_NEG, TRIT_POS)
        and   r2 = compare(TRIT_POS, TRIT_NEG)
        assert r1 == TRIT_NEG and r2 == TRIT_POS

    invariant branch_if_eq_branch_if_not
        given v = TRIT_ZERO
        and   b1 = branch_if(v, 5)
        and   b2 = branch_if_not(v, 5)
        assert b1 == false and b2 == true

    invariant branch_if_not_eq_branch_if
        given v = TRIT_POS
        and   b1 = branch_if(v, 5)
        and   b2 = branch_if_not(v, 5)
        assert b1 == true and b2 == false

    invariant jump_relative_symmetric
        given pc_before = pc_relative(0)
        and   jump_relative(10)
        and   pc_after = pc_read()
        and   jump_relative(-10)
        and   pc_final = pc_read()
        assert pc_before == pc_final

    invariant table_branch_in_range
        given table = []u32{100, 200, 300}
        and   table_branch(0, table, 999)
        and   table_branch(1, table, 999)
        and   table_branch(2, table, 999)
        // All indices 0, 1, 2 should branch to 100, 200, 300
        assert true

    invariant trit_condition_values
        assert TRIT_NEG == -1 and TRIT_ZERO == 0 and TRIT_POS == 1

    bench branch_cond_latency
        measure: nanoseconds to branch_cond(TRIT_POS, COND_POS, 10)
        target: < 100ns

    bench compare_latency
        measure: nanoseconds to compare(TRIT_POS, TRIT_NEG)
        target: < 50ns

    bench jump_relative_latency
        measure: nanoseconds to jump_relative(10)
        target: < 50ns

    bench jump_link_latency
        measure: nanoseconds to jump_link(100, &lr)
        target: < 80ns

    bench ret_latency
        measure: nanoseconds to ret(50)
        target: < 60ns

    bench table_branch_latency
        measure: nanoseconds to table_branch(1, []u32{100, 200, 300}, 999)
        target: < 150ns
}

// SPDX-License-Identifier: Apache-2.0
; fp8_e4m3.t27 — FP8 E4M3 8-bit Floating Point
; 8-bit float with 4 exponent, 3 mantissa bits (no implicit leading bit)
; OCP FP8 format optimized for neural network training
; Range: ~-240 to ~240, precision: ~6-7 significant bits
; φ² + 1/φ² = 3 | TRINITY

module triformat-fp8_e4m3;

// ============================================================================
// Constants
// ============================================================================

pub const BITS : u8 = 8;
pub const SIGN_BITS : u8 = 1;
pub const EXP_BITS : u8 = 4;
pub const MANT_BITS : u8 = 3;

pub const SIGN_SHIFT : u8 = 7;
pub const EXP_SHIFT : u8 = 3;
pub const MANT_SHIFT : u8 = 0;

pub const SIGN_MASK : u8 = 0x80;    // 1 << 7
pub const EXP_MASK : u8 = 0x78;     // 0b01111000
pub const MANT_MASK : u8 = 0x07;    // 0b00000111

pub const EXP_MAX : u8 = 15;         // All ones in 4 bits
pub const EXP_MIN : u8 = 0;
pub const EXP_BIAS : u8 = 7;         // Exponent bias for FP8 E4M3

pub const MANT_DIVISOR : u8 = 8;     // 2^3

// FP8 E4M3 special values
pub const FP8_ZERO_POS : u8 = 0x00;
pub const FP8_ZERO_NEG : u8 = 0x80;
pub const FP8_NAN_POS : u8 = 0x7F;   // All exp + mant != 0
pub const FP8_NAN_NEG : u8 = 0xFF;
pub const FP8_INF_POS : u8 = 0x78;   // All exp + mant = 0
pub const FP8_INF_NEG : u8 = 0xF8;

// Subnormal exponent
pub const SUBNORMAL_EXP : u8 = 0;

// ============================================================================
// Types
// ============================================================================

pub const FP8E4M3 = u8;  // 8-bit value

// ============================================================================
// Extract Functions
// ============================================================================

// fp8_extract_sign(fp8: FP8E4M3) -> i8
// Extract sign bit (bit 7)
// Returns: 0 for positive, -1 for negative
pub fn fp8_extract_sign(fp8: FP8E4M3) i8 {
    const bit = (fp8 >> SIGN_SHIFT) & 1;
    return if (bit != 0) -1 else 0;
}

// fp8_extract_exponent(fp8: FP8E4M3) -> u8
// Extract exponent bits (bits 6-3)
// Returns: 0-15
pub fn fp8_extract_exponent(fp8: FP8E4M3) u8 {
    return (fp8 >> EXP_SHIFT) & 0x0F;
}

// fp8_extract_mantissa(fp8: FP8E4M3) -> u8
// Extract mantissa bits (bits 2-0)
// Returns: 0-7
pub fn fp8_extract_mantissa(fp8: FP8E4M3) u8 {
    return fp8 & MANT_MASK;
}

// fp8_from_components(sign: i8, exp: u8, mant: u8) -> FP8E4M3
// Assemble FP8 from sign, exponent, mantissa
pub fn fp8_from_components(sign: i8, exp: u8, mant: u8) FP8E4M3 {
    const sign_bit = if (sign < 0) 1 else 0;
    return (@as(FP8E4M3, @intCast(sign_bit)) << SIGN_SHIFT) |
           (@as(FP8E4M3, @intCast(exp & 0x0F)) << EXP_SHIFT) |
           (mant & MANT_MASK);
}

// ============================================================================
// Special Value Checks
// ============================================================================

// fp8_is_zero(fp8: FP8E4M3) -> bool
// Check if FP8 is zero (positive or negative)
pub fn fp8_is_zero(fp8: FP8E4M3) bool {
    return fp8 == FP8_ZERO_POS or fp8 == FP8_ZERO_NEG;
}

// fp8_is_special(fp8: FP8E4M3) -> bool
// Check if FP8 is Inf or NaN (exp == 15)
pub fn fp8_is_special(fp8: FP8E4M3) bool {
    return fp8_extract_exponent(fp8) == EXP_MAX;
}

// fp8_is_inf(fp8: FP8E4M3) -> bool
// Check if FP8 is infinity (exp == 15, mant == 0)
pub fn fp8_is_inf(fp8: FP8E4M3) bool {
    return fp8_extract_exponent(fp8) == EXP_MAX and fp8_extract_mantissa(fp8) == 0;
}

// fp8_is_nan(fp8: FP8E4M3) -> bool
// Check if FP8 is NaN (exp == 15, mant != 0)
pub fn fp8_is_nan(fp8: FP8E4M3) bool {
    return fp8_extract_exponent(fp8) == EXP_MAX and fp8_extract_mantissa(fp8) != 0;
}

// fp8_is_subnormal(fp8: FP8E4M3) -> bool
// Check if FP8 is subnormal (exp == 0, mant != 0)
pub fn fp8_is_subnormal(fp8: FP8E4M3) bool {
    return fp8_extract_exponent(fp8) == 0 and fp8_extract_mantissa(fp8) != 0;
}

// ============================================================================
// Encode/Decode Functions
// ============================================================================

// fp8_encode_f32(value: f32) -> FP8E4M3
// Encode IEEE 754 single precision to FP8 E4M3
// Round-to-nearest, ties to even
pub fn fp8_encode_f32(value: f32) FP8E4M3 {
    // Handle zero
    if (value == 0.0) {
        return if (std.math.signbit(value)) FP8_ZERO_NEG else FP8_ZERO_POS;
    }

    // Handle NaN
    if (std.math.isNan(value)) {
        return if (value < 0.0) FP8_NAN_NEG else FP8_NAN_POS;
    }

    // Handle Infinity
    if (std.math.isInf(value)) {
        return if (value < 0.0) FP8_INF_NEG else FP8_INF_POS;
    }

    // Extract sign
    const sign = if (value < 0.0) -1 else 0;
    const abs_value = if (value < 0.0) -value else value;

    // Get f32 components
    const f32_bits: u32 = @bitCast(abs_value);
    var f32_exp: i16 = @as(i16, @intCast((f32_bits >> 23) & 0xFF)) - 127;
    var f32_mant: u32 = f32_bits & 0x007FFFFF;

    // Handle very small values (subnormals)
    if (f32_exp <= @as(i16, -EXP_BIAS)) {
        // Below FP8 minimum normal - try to encode as subnormal
        const subnormal_shift = @as(i16, -EXP_BIAS) - f32_exp + 1;
        if (subnormal_shift > 3 + 23) {
            return if (sign < 0) FP8_ZERO_NEG else FP8_ZERO_POS;
        }
        var mant = f32_mant >> 23;
        if (subnormal_shift > 0) {
            const shift_amount = @as(u5, @intCast(subnormal_shift));
            if (shift_amount <= 24) {
                mant = (f32_mant | 0x00800000) >> shift_amount;
            }
        }
        return fp8_from_components(sign, 0, @as(u8, @truncate(mant)) & 0x07);
    }

    // Convert exp from f32 bias (127) to FP8 bias (7)
    var fp8_exp = @as(i16, f32_exp + EXP_BIAS);

    // Clamp exponent
    if (fp8_exp >= EXP_MAX) {
        return if (sign < 0) FP8_INF_NEG else FP8_INF_POS;
    } else if (fp8_exp < 1) {
        // Underflow to zero (could be subnormal, simplified)
        return if (sign < 0) FP8_ZERO_NEG else FP8_ZERO_POS;
    }

    // Extract mantissa and scale to 3 bits
    // f32 mantissa is 24 bits (including implicit 1), FP8 needs 3 bits
    // Shift right by 21 bits (24 - 3 = 21)
    var mant = f32_mant >> 21;

    // Round-to-nearest with ties to even
    const discarded = f32_mant & 0x1FFFFF;  // Lower 21 bits
    if ((discarded & 0x100000) != 0) {
        // Halfway or more
        if ((discarded & 0x0FFFFF) != 0 or (mant & 1) != 0) {
            mant += 1;
            if (mant > MANT_MASK) {
                mant = 0;
                if (fp8_exp < @as(i16, EXP_MAX - 1)) {
                    fp8_exp += 1;
                }
            }
        }
    }

    return fp8_from_components(sign, @as(u8, @intCast(fp8_exp)), @as(u8, mant));
}

// fp8_decode_f32(fp8: FP8E4M3) -> f32
// Decode FP8 E4M3 to IEEE 754 single precision
pub fn fp8_decode_f32(fp8: FP8E4M3) f32 {
    // Handle zero
    if (fp8_is_zero(fp8)) {
        return if (fp8_extract_sign(fp8) < 0) -0.0 else 0.0;
    }

    // Handle NaN
    if (fp8_is_nan(fp8)) {
        return std.math.nan(f32);
    }

    // Handle Infinity
    if (fp8_is_inf(fp8)) {
        return if (fp8_extract_sign(fp8) < 0) -std.math.inf(f32) else std.math.inf(f32);
    }

    // Extract components
    const sign = fp8_extract_sign(fp8);
    const exp = fp8_extract_exponent(fp8);
    const mant = fp8_extract_mantissa(fp8);

    var f32_value: f32 = undefined;

    // Handle subnormal
    if (exp == 0) {
        // Subnormal: value = mant * 2^(-6) = mant * 2^(1-bias)
        const bias_adjusted: i8 = 1 - @as(i8, EXP_BIAS);
        const mant_f32 = @as(f32, @floatFromInt(mant)) / @as(f32, @floatFromInt(MANT_DIVISOR));
        f32_value = mant_f32 * std.math.pow(f32, 2.0, @as(f32, @floatFromInt(bias_adjusted)));
    } else {
        // Normal: value = (1 + mant/8) * 2^(exp - 7)
        const bias_adjusted = @as(i16, exp) - @as(i16, EXP_BIAS);
        const mant_f32 = 1.0 + (@as(f32, @floatFromInt(mant)) / @as(f32, @floatFromInt(MANT_DIVISOR)));
        f32_value = mant_f32 * std.math.pow(f32, 2.0, @as(f32, @floatFromInt(bias_adjusted)));
    }

    return if (sign < 0) -f32_value else f32_value;
}

// fp8_encode_f64(value: f64) -> FP8E4M3
// Encode IEEE 754 double precision to FP8 E4M3
pub fn fp8_encode_f64(value: f64) FP8E4M3 {
    return fp8_encode_f32(@as(f32, @floatCast(value)));
}

// fp8_decode_f64(fp8: FP8E4M3) -> f64
// Decode FP8 E4M3 to IEEE 754 double precision
pub fn fp8_decode_f64(fp8: FP8E4M3) f64 {
    const f32_val = fp8_decode_f32(fp8);
    return @as(f64, @floatFromInt(f32_val));
}

// ============================================================================
// Arithmetic Operations
// ============================================================================

// fp8_add(a: FP8E4M3, b: FP8E4M3) -> FP8E4M3
// Add two FP8 values
pub fn fp8_add(a: FP8E4M3, b: FP8E4M3) FP8E4M3 {
    const fa = fp8_decode_f32(a);
    const fb = fp8_decode_f32(b);
    return fp8_encode_f32(fa + fb);
}

// fp8_sub(a: FP8E4M3, b: FP8E4M3) -> FP8E4M3
// Subtract two FP8 values
pub fn fp8_sub(a: FP8E4M3, b: FP8E4M3) FP8E4M3 {
    const fa = fp8_decode_f32(a);
    const fb = fp8_decode_f32(b);
    return fp8_encode_f32(fa - fb);
}

// fp8_mul(a: FP8E4M3, b: FP8E4M3) -> FP8E4M3
// Multiply two FP8 values
pub fn fp8_mul(a: FP8E4M3, b: FP8E4M3) FP8E4M3 {
    const fa = fp8_decode_f32(a);
    const fb = fp8_decode_f32(b);
    return fp8_encode_f32(fa * fb);
}

// fp8_div(a: FP8E4M3, b: FP8E4M3) -> FP8E4M3
// Divide two FP8 values
pub fn fp8_div(a: FP8E4M3, b: FP8E4M3) FP8E4M3 {
    const fb = fp8_decode_f32(b);
    if (fb == 0.0) {
        const fa = fp8_decode_f32(a);
        return if (fa < 0.0) FP8_INF_NEG else FP8_INF_POS;
    }
    const fa = fp8_decode_f32(a);
    return fp8_encode_f32(fa / fb);
}

// fp8_sqrt(value: FP8E4M3) -> FP8E4M3
// Square root of FP8 value
pub fn fp8_sqrt(value: FP8E4M3) FP8E4M3 {
    const fv = fp8_decode_f32(value);
    if (fv < 0.0) {
        return FP8_NAN_POS;
    }
    return fp8_encode_f32(std.math.sqrt(fv));
}

// fp8_rsqrt(value: FP8E4M3) -> FP8E4M3
// Reciprocal square root (1/sqrt(x))
pub fn fp8_rsqrt(value: FP8E4M3) FP8E4M3 {
    const fv = fp8_decode_f32(value);
    if (fv <= 0.0) {
        return FP8_INF_POS;
    }
    return fp8_encode_f32(1.0 / std.math.sqrt(fv));
}

// fp8_abs(value: FP8E4M3) -> FP8E4M3
// Absolute value of FP8
pub fn fp8_abs(value: FP8E4M3) FP8E4M3 {
    return value & ~SIGN_MASK;
}

// fp8_neg(value: FP8E4M3) -> FP8E4M3
// Negate FP8
pub fn fp8_neg(value: FP8E4M3) FP8E4M3 {
    return value ^ SIGN_MASK;
}

// fp8_is_equal(a: FP8E4M3, b: FP8E4M3) -> bool
// Check if two FP8 values are equal
pub fn fp8_is_equal(a: FP8E4M3, b: FP8E4M3) bool {
    if (fp8_is_nan(a) or fp8_is_nan(b)) {
        return false;
    }
    if (fp8_is_zero(a) and fp8_is_zero(b)) {
        return true;
    }
    return a == b;
}

// fp8_is_greater(a: FP8E4M3, b: FP8E4M3) -> bool
// Check if a > b
pub fn fp8_is_greater(a: FP8E4M3, b: FP8E4M3) bool {
    if (fp8_is_nan(a) or fp8_is_nan(b)) {
        return false;
    }
    const sign_a = fp8_extract_sign(a);
    const sign_b = fp8_extract_sign(b);
    if (sign_a != sign_b) {
        return sign_a > sign_b;
    }
    if (sign_a < 0) {
        return fp8_neg(a) > fp8_neg(b);
    }
    return a > b;
}

// fp8_max(a: FP8E4M3, b: FP8E4M3) -> FP8E4M3
// Return the larger of two FP8 values
pub fn fp8_max(a: FP8E4M3, b: FP8E4M3) FP8E4M3 {
    return if (fp8_is_greater(a, b)) a else b;
}

// fp8_min(a: FP8E4M3, b: FP8E4M3) -> FP8E4M3
// Return the smaller of two FP8 values
pub fn fp8_min(a: FP8E4M3, b: FP8E4M3) FP8E4M3 {
    return if (fp8_is_greater(a, b)) b else a;
}

// fp8_clamp(value: FP8E4M3, min: FP8E4M3, max: FP8E4M3) -> FP8E4M3
// Clamp value between min and max
pub fn fp8_clamp(value: FP8E4M3, min: FP8E4M3, max: FP8E4M3) FP8E4M3 {
    return fp8_min(fp8_max(value, min), max);
}

// fp8_lerp(a: FP8E4M3, b: FP8E4M3, t: f32) -> FP8E4M3
// Linear interpolation between a and b
pub fn fp8_lerp(a: FP8E4M3, b: FP8E4M3, t: f32) FP8E4M3 {
    const fa = fp8_decode_f32(a);
    const fb = fp8_decode_f32(b);
    const result = fa + (fb - fa) * t;
    return fp8_encode_f32(result);
}

// fp8_fma(a: FP8E4M3, b: FP8E4M3, c: FP8E4M3) -> FP8E4M3
// Fused multiply-add: a * b + c
pub fn fp8_fma(a: FP8E4M3, b: FP8E4M3, c: FP8E4M3) FP8E4M3 {
    const fa = fp8_decode_f32(a);
    const fb = fp8_decode_f32(b);
    const fc = fp8_decode_f32(c);
    return fp8_encode_f32(fa * fb + fc);
}

// fp8_scale(value: FP8E4M3, scale: f32) -> FP8E4M3
// Scale FP8 value by scalar
pub fn fp8_scale(value: FP8E4M3, scale: f32) FP8E4M3 {
    const fv = fp8_decode_f32(value);
    return fp8_encode_f32(fv * scale);
}

// fp8_relu(value: FP8E4M3) -> FP8E4M3
// ReLU activation: max(0, x)
pub fn fp8_relu(value: FP8E4M3) FP8E4M3 {
    return if (fp8_extract_sign(value) < 0) FP8_ZERO_POS else value;
}

// fp8_sigmoid(value: FP8E4M3) -> FP8E4M3
// Sigmoid activation: 1 / (1 + e^(-x))
pub fn fp8_sigmoid(value: FP8E4M3) FP8E4M3 {
    const fv = fp8_decode_f32(value);
    return fp8_encode_f32(1.0 / (1.0 + std.math.exp(-fv)));
}

// fp8_tanh(value: FP8E4M3) -> FP8E4M3
// Tanh activation
pub fn fp8_tanh(value: FP8E4M3) FP8E4M3 {
    const fv = fp8_decode_f32(value);
    return fp8_encode_f32(std.math.tanh(fv));
}

// fp8_gelu(value: FP8E4M3) -> FP8E4M3
// GELU activation
pub fn fp8_gelu(value: FP8E4M3) FP8E4M3 {
    const fv = fp8_decode_f32(value);
    const sqrt_2_over_pi = 0.7978845608;
    const cube_coeff = 0.044715;
    const tanh_arg = fv * (1.0 + cube_coeff * fv * fv);
    return fp8_encode_f32(0.5 * fv * (1.0 + std.math.tanh(sqrt_2_over_pi * tanh_arg)));
}

// fp8_swish(value: FP8E4M3) -> FP8E4M3
// Swish activation: x * sigmoid(x)
pub fn fp8_swish(value: FP8E4M3) FP8E4M3 {
    const fv = fp8_decode_f32(value);
    return fp8_encode_f32(fv * (1.0 / (1.0 + std.math.exp(-fv))));
}

// fp8_quantize_to_int4(value: FP8E4M3) -> i8
// Quantize FP8 to Int4 (range [-8, 7])
pub fn fp8_quantize_to_int4(value: FP8E4M3) i8 {
    const fv = fp8_decode_f32(value);
    const scaled = fv * 7.0;
    var result: i32 = @intFromFloat(@round(scaled));
    if (result > 7) {
        result = 7;
    } else if (result < -8) {
        result = -8;
    }
    return @as(i8, @intCast(result));
}

// fp8_quantize_to_int8(value: FP8E4M3) -> i8
// Quantize FP8 to Int8 (range [-128, 127])
pub fn fp8_quantize_to_int8(value: FP8E4M3) i8 {
    const fv = fp8_decode_f32(value);
    const scaled = fv * 127.0;
    var result: i32 = @intFromFloat(@round(scaled));
    if (result > 127) {
        result = 127;
    } else if (result < -128) {
        result = -128;
    }
    return @as(i8, @intCast(result));
}

// ============================================================================
// TDD Tests
// ============================================================================

test "fp8_extract_sign_positive" {
    given value = 0x3C
    try std.testing.expect(sign = fp8_extract_sign(value));
    try std.testing.expect(sign == 0);
}

test "fp8_extract_sign_negative" {
    given value = 0xBC
    try std.testing.expect(sign = fp8_extract_sign(value));
    try std.testing.expect(sign == -1);
}

test "fp8_extract_exponent_max" {
    given value = 0x78
    try std.testing.expect(exp = fp8_extract_exponent(value));
    try std.testing.expect(exp == EXP_MAX);
}

test "fp8_extract_exponent_zero" {
    given value = 0x07
    try std.testing.expect(exp = fp8_extract_exponent(value));
    try std.testing.expect(exp == 0);
}

test "fp8_extract_mantissa_max" {
    given value = 0x07
    try std.testing.expect(mant = fp8_extract_mantissa(value));
    try std.testing.expect(mant == MANT_MASK);
}

test "fp8_is_zero_positive" {
    try std.testing.expect(fp8_is_zero(FP8_ZERO_POS) == true);
}

test "fp8_is_zero_negative" {
    try std.testing.expect(fp8_is_zero(FP8_ZERO_NEG) == true);
}

test "fp8_is_zero_nonzero" {
    try std.testing.expect(fp8_is_zero(0x01) == false);
}

test "fp8_is_inf_positive" {
    try std.testing.expect(fp8_is_inf(FP8_INF_POS) == true);
}

test "fp8_is_inf_negative" {
    try std.testing.expect(fp8_is_inf(FP8_INF_NEG) == true);
