// SPDX-License-Identifier: Apache-2.0
// lsp/protocol.t27 — JSON-RPC 2.0 Protocol Mapping
// LSP message handling over JSON-RPC transport layer
// φ² + 1/φ² = 3 | TRINITY

module lsp-protocol;

// ============================================================================
// Imports
// ============================================================================

use tritype-base::usize;

// ============================================================================
// Constants
// ============================================================================

/// JSON-RPC version string
pub const JSON_RPC_VERSION : []const u8 = "2.0";

/// Default buffer size for message encoding
pub const DEFAULT_BUFFER_SIZE : usize = 4096;

/// Maximum message length in bytes
pub const MAX_MESSAGE_LENGTH : usize = 10485760;

/// Request method for initialize
pub const METHOD_INITIALIZE : []const u8 = "initialize";

/// Request method for initialized
pub const METHOD_INITIALIZED : []const u8 = "initialized";

/// Request method for shutdown
pub const METHOD_SHUTDOWN : []const u8 = "shutdown";

/// Request method for exit
pub const METHOD_EXIT : []const u8 = "exit";

/// Request method for textDocument/didOpen
pub const METHOD_DID_OPEN : []const u8 = "textDocument/didOpen";

/// Request method for textDocument/didChange
pub const METHOD_DID_CHANGE : []const u8 = "textDocument/didChange";

/// Request method for textDocument/didClose
pub const METHOD_DID_CLOSE : []const u8 = "textDocument/didClose";

/// Request method for textDocument/completion
pub const METHOD_COMPLETION : []const u8 = "textDocument/completion";

/// Request method for textDocument/hover
pub const METHOD_HOVER : []const u8 = "textDocument/hover";

/// Request method for textDocument/definition
pub const METHOD_DEFINITION : []const u8 = "textDocument/definition";

/// Request method for textDocument/documentSymbol
pub const METHOD_DOCUMENT_SYMBOL : []const u8 = "textDocument/documentSymbol";

/// Request method for workspace/symbol
pub const METHOD_WORKSPACE_SYMBOL : []const u8 = "workspace/symbol";

/// Request method for textDocument/codeAction
pub const METHOD_CODE_ACTION : []const u8 = "textDocument/codeAction";

/// Request method for textDocument/rename
pub const METHOD_RENAME : []const u8 = "textDocument/rename";

// ============================================================================
// Types
// ============================================================================

/// JSON-RPC message type
pub const MessageType = enum(u8) {
    request = 0,
    response = 1,
    notification = 2,
    error = 3,
};

/// JSON-RPC request
pub const Request = struct {
    jsonrpc : []const u8,
    id : usize,
    method : []const u8,
    params : []const u8,
};

/// JSON-RPC response
pub const Response = struct {
    jsonrpc : []const u8,
    id : usize,
    result : []const u8,
    error : []const u8,
};

/// JSON-RPC notification
pub const Notification = struct {
    jsonrpc : []const u8,
    method : []const u8,
    params : []const u8,
};

/// JSON-RPC error
pub const JsonRpcError = struct {
    code : i32,
    message : []const u8,
    data : []const u8,
};

/// Message parsing result
pub const ParseResult = struct {
    success : bool,
    message_type : MessageType,
    request : Request,
    response : Response,
    notification : Notification,
    error : JsonRpcError,
};

/// Transport layer type
pub const TransportType = enum(u8) {
    stdio = 0,
    tcp = 1,
    websocket = 2,
};

/// Connection state
pub const ConnectionState = enum(u8) {
    disconnected = 0,
    connecting = 1,
    connected = 2,
    error = 3,
};

/// Message buffer
/// A message buffer that owns its storage.
///
/// `data` is `[]u8`, not `[]const u8`: a buffer whose bytes cannot be written
/// is not a buffer. The previous shape paired a mutable-sounding `capacity`
/// with an immutable empty slice, which is how it managed to claim room for
/// 1024 bytes while holding none.
pub const MessageBuffer = struct {
    data : []u8,
    length : usize,
    capacity : usize,
};

/// Incoming message
pub const IncomingMessage = struct {
    content : []const u8,
    complete : bool,
};

/// Outgoing message
pub const OutgoingMessage = struct {
    content : []const u8,
    sent : bool,
};

/// Batch request
pub const BatchRequest = struct {
    requests : []Request,
};

/// Batch response
pub const BatchResponse = struct {
    responses : []Response,
};

/// Cancel params
pub const CancelParams = struct {
    id : usize,
};

// ============================================================================
// Functions
// ============================================================================

/// Create JSON-RPC request
pub fn request_create(id: usize, method: []const u8, params: []const u8) Request {
    return Request{
        .jsonrpc = JSON_RPC_VERSION,
        .id = id,
        .method = method,
        .params = params,
    };
}

/// Create JSON-RPC response
pub fn response_create(id: usize, result: []const u8) Response {
    return Response{
        .jsonrpc = JSON_RPC_VERSION,
        .id = id,
        .result = result,
        .error = "",
    };
}

/// Create JSON-RPC error response
pub fn response_error_create(id: usize, err: JsonRpcError) Response {
    return Response{
        .jsonrpc = JSON_RPC_VERSION,
        .id = id,
        .result = "",
        .error = err.message,
    };
}

/// Create JSON-RPC notification
pub fn notification_create(method: []const u8, params: []const u8) Notification {
    return Notification{
        .jsonrpc = JSON_RPC_VERSION,
        .method = method,
        .params = params,
    };
}

/// Create JSON-RPC error
pub fn json_rpc_error_create(code: i32, message: []const u8) JsonRpcError {
    return JsonRpcError{
        .code = code,
        .message = message,
        .data = "",
    };
}

/// Create a message buffer with room for `capacity` bytes.
///
/// Takes an allocator and returns an error union because it genuinely can
/// fail: asking for room is not the same as having it. The old signature
/// promised a buffer it could not deliver, and no signature without an
/// allocator can deliver one -- that is why the honest test was left red
/// rather than patched.
///
/// Caller owns the result; pass it to message_buffer_destroy.
pub fn message_buffer_create(allocator: std.mem.Allocator, capacity: usize) !MessageBuffer {
    const data = try allocator.alloc(u8, capacity);
    return MessageBuffer{
        .data = data,
        .length = 0,
        .capacity = capacity,
    };
}

/// Release a buffer's storage. Pair with message_buffer_create.
pub fn message_buffer_destroy(allocator: std.mem.Allocator, buf: MessageBuffer) void {
    allocator.free(buf.data);
}

/// Create initialize request
pub fn initialize_request_create(id: usize, params: []const u8) Request {
    return request_create(id, METHOD_INITIALIZE, params);
}

/// Create initialized notification
pub fn initialized_notification_create() Notification {
    return notification_create(METHOD_INITIALIZED, "");
}

/// Create shutdown request
pub fn shutdown_request_create(id: usize) Request {
    return request_create(id, METHOD_SHUTDOWN, "");
}

/// Create exit notification
pub fn exit_notification_create() Notification {
    return notification_create(METHOD_EXIT, "");
}

/// Create completion request
pub fn completion_request_create(id: usize, params: []const u8) Request {
    return request_create(id, METHOD_COMPLETION, params);
}

/// Create hover request
pub fn hover_request_create(id: usize, params: []const u8) Request {
    return request_create(id, METHOD_HOVER, params);
}

/// Create definition request
pub fn definition_request_create(id: usize, params: []const u8) Request {
    return request_create(id, METHOD_DEFINITION, params);
}

/// Create cancel params
pub fn cancel_params_create(id: usize) CancelParams {
    return CancelParams{
        .id = id,
    };
}

/// Check if response is successful
pub fn response_is_success(resp: Response) bool {
    return resp.result.len > 0;
}

/// Check if response has error
pub fn response_has_error(resp: Response) bool {
    return resp.error.len > 0;
}

/// Check if message is notification
pub fn message_is_notification(msg: ParseResult) bool {
    return msg.message_type == .notification;
}

/// Check if message is request
pub fn message_is_request(msg: ParseResult) bool {
    return msg.message_type == .request;
}

/// Get message type string
pub fn message_type_to_string(msg_type: MessageType) []const u8 {
    return switch (msg_type) {
        .request => "request",
        .response => "response",
        .notification => "notification",
        .error => "error",
    };
}

/// Check if connection is active
pub fn connection_is_active(state: ConnectionState) bool {
    return state == .connected;
}

/// Get connection state string
pub fn connection_state_to_string(state: ConnectionState) []const u8 {
    return switch (state) {
        .disconnected => "disconnected",
        .connecting => "connecting",
        .connected => "connected",
        .error => "error",
    };
}

/// Create parse result
pub fn parse_result_create(success: bool, message_type: MessageType) ParseResult {
    return ParseResult{
        .success = success,
        .message_type = message_type,
        .request = request_create(0, "", ""),
        .response = response_create(0, ""),
        .notification = notification_create("", ""),
        .error = json_rpc_error_create(0, ""),
    };
}

/// Check if transport supports duplex communication
pub fn transport_supports_duplex(trans_type: TransportType) bool {
    return trans_type == .stdio or trans_type == .tcp or trans_type == .websocket;
}

