}

test "lsp_message_buffer_create" {
    const buf = try message_buffer_create(std.testing.allocator, 1024);
    defer message_buffer_destroy(std.testing.allocator, buf);
    try std.testing.expect(buf.capacity == 1024);
}

// This was red on purpose until 2026-08-27: message_buffer_create reported
// whatever capacity it was asked for and backed it with nothing -- `.data =
// ""`, an empty slice, for any argument. The test above passed because it
// read only `capacity`, the field the function copied rather than the one it
// would have had to earn.
//
// The signature now takes an allocator and returns an error union, so the
// claim is backed or the call fails. std.testing.allocator is deliberate: it
// fails the test on a leak, so this also pins that message_buffer_destroy
// actually frees.
test "lsp_message_buffer_has_the_room_it_claims" {
    const buf = try message_buffer_create(std.testing.allocator, 1024);
    defer message_buffer_destroy(std.testing.allocator, buf);
    try std.testing.expect(buf.data.len >= buf.capacity);
}

// The other half of the promise: a buffer that cannot be written is not a
// buffer, whatever its length says.
test "lsp_message_buffer_is_writable" {
    const buf = try message_buffer_create(std.testing.allocator, 8);
    defer message_buffer_destroy(std.testing.allocator, buf);
    buf.data[0] = 0xAB;
    buf.data[7] = 0xCD;
    try std.testing.expect(buf.data[0] == 0xAB);
    try std.testing.expect(buf.data[7] == 0xCD);
}

// A zero-capacity buffer is legal and must still round-trip through destroy
// without the allocator complaining.
test "lsp_message_buffer_zero_capacity" {
    const buf = try message_buffer_create(std.testing.allocator, 0);
    defer message_buffer_destroy(std.testing.allocator, buf);
    try std.testing.expect(buf.data.len == 0);
    try std.testing.expect(buf.capacity == 0);
}

