    // TransportType is valid enum value
    @compileAssert(true);
}

invariant connection_state_in_range {
    // ConnectionState is in [0, 3]
    @compileAssert(@intFromEnum(ConnectionState.disconnected) == 0);
    @compileAssert(@intFromEnum(ConnectionState.error) == 3);
}

invariant json_rpc_error_has_code {
    // JsonRpcError has valid error code
    @compileAssert(true);
}

invariant message_buffer_capacity_positive {
    // MessageBuffer capacity is positive
    @compileAssert(true);
}

invariant method_strings_valid {
    // All method constants are non-empty
    @compileAssert(METHOD_INITIALIZE.len > 0);
    @compileAssert(METHOD_EXIT.len > 0);
}

