// t27/specs/numeric/int8.t27
// Int8 - 8-bit signed integer
// NUMERIC-STANDARD-001 Agent 10 (P1)

module Int8 {
    // Import test/invariant/bench framework
    use base::testing;
    use base::benchmarking;

    // 1. Format Definition
    // Int8 bit layout: S(7) - 8-bit two's complement
    //   S: 8 bits (signed 8-bit integer)
    //
    // Range: -128 to 127
    // 256 possible values

    const BITS : u8 = 8;

    // 2. Int8 Type

    struct Int8 {
        raw : u8,  // 8-bit raw value (two's complement)
    }

    // 3. Encoding/Decoding

    // Encode i32 to Int8 (clamp to range)
    fn encode(value: i32) -> Int8 {
        const clamped = if (value > 127) { 127 } else if (value < -128) { -128 } else { value };
        // Two's complement: negative values are stored as 2^8 + value
        let raw = clamped as u8;
        if (clamped < 0) {
            raw = (256 + clamped) as u8;
        }
        return Int8{ raw = raw };
    }

    // Decode Int8 to i32
    fn decode(i: Int8) -> i32 {
        const raw = i.raw as i32;
        // Two's complement: if sign bit set, negative
        if (raw >= 128) {
            return raw - 256;
        }
        return raw;
    }

    // 4. Format Properties

    fn min_value() -> i32 {
        return -128;
    }

    fn max_value() -> i32 {
        return 127;
    }

    fn range() -> i32 {
        return max_value() - min_value();
    }

    fn num_values() -> i32 {
        return 256;
    }

    // 5. Validation

    fn validate_format() -> bool {
        return BITS == 8;
    }

    // 6. Use Cases

    // Int8 is optimal for:
    // - Standard integer quantization (75% smaller than INT32)
    // - Neural network weight quantization
    // - Activation caching
    // - General-purpose integer arithmetic
    // - Control and status registers

    // Memory: 8 bits = 1 byte (4x INT32 in same space)
    const MEMORY_RATIO_VS_FP32 : f32 = 8.0 / 32.0;  // 0.25

    // 7. Arithmetic Operations

    fn add(a: Int8, b: Int8) -> Int8 {
        const val_a = decode(a);
        const val_b = decode(b);
        const result = val_a + val_b;
        return encode(result);
    }

    fn sub(a: Int8, b: Int8) -> Int8 {
        const val_a = decode(a);
        const val_b = decode(b);
        const result = val_a - val_b;
        return encode(result);
    }

    fn mul(a: Int8, b: Int8) -> Int8 {
        const val_a = decode(a);
        const val_b = decode(b);
        const result = val_a * val_b;
        return encode(result);
    }

    fn div(a: Int8, b: Int8) -> Int8 {
        const val_a = decode(a);
        const val_b = decode(b);
        const result = if (val_b != 0) { val_a / val_b } else { 0 };
        return encode(result);
    }

    fn mod(a: Int8, b: Int8) -> Int8 {
        const val_a = decode(a);
        const val_b = decode(b);
        const result = if (val_b != 0) { val_a % val_b } else { 0 };
        return encode(result);
    }

    fn neg(i: Int8) -> Int8 {
        return encode(-decode(i));
    }

    fn abs(i: Int8) -> Int8 {
        const val = decode(i);
        return encode(if (val < 0) { -val } else { val });
    }

    // 8. Comparison Operations

    fn eq(a: Int8, b: Int8) -> bool {
        return decode(a) == decode(b);
    }

    fn ne(a: Int8, b: Int8) -> bool {
        return decode(a) != decode(b);
    }

    fn lt(a: Int8, b: Int8) -> bool {
        return decode(a) < decode(b);
    }

    fn le(a: Int8, b: Int8) -> bool {
        return decode(a) <= decode(b);
    }

    fn gt(a: Int8, b: Int8) -> bool {
        return decode(a) > decode(b);
    }

    fn ge(a: Int8, b: Int8) -> bool {
        return decode(a) >= decode(b);
    }

    // 9. Bitwise Operations

    fn and(a: Int8, b: Int8) -> Int8 {
        return Int8{ raw = a.raw & b.raw };
    }

    fn or(a: Int8, b: Int8) -> Int8 {
        return Int8{ raw = a.raw | b.raw };
    }

    fn xor(a: Int8, b: Int8) -> Int8 {
        return Int8{ raw = a.raw ^ b.raw };
    }

    fn not(i: Int8) -> Int8 {
        return Int8{ raw = i.raw ^ 0xFF };
    }

    fn shl(a: Int8, shift: u8) -> Int8 {
        const clamped_shift = if (shift > 7) { 7 } else { shift };
        return Int8{ raw = (a.raw << clamped_shift) & 0xFF };
    }

    fn shr(a: Int8, shift: u8) -> Int8 {
        const clamped_shift = if (shift > 7) { 7 } else { shift };
        // Arithmetic shift for negative numbers
        const val = decode(a);
        const result = val >> (clamped_shift as i32);
        return encode(result);
    }

    // TDD-Inside-Spec: Tests and Invariants for Int8

